# Track 7 Bagian C — PM-C1..C11 (CFA L3 slice)
LESSONS = [{'slug': 'pm-c1-ips', 'id': 'PM-C1', 'track': 'Portfolio Management', 'title_html': 'IPS:<br/>Wealth, Institusi & Pajak', 'title_plain': 'IPS: Individu & Institusi, Tax-Aware Investing', 'chapter_summary': 'CFA L3: Investment Policy Statement mendalam — objectives & constraints, private wealth vs institusi (pensiun, endowment, asuransi), dan tax-aware investing (tax-loss harvesting, asset location). Lab generator IPS & kalkulator tax-loss harvesting.', 'tujuan': ['Menjelaskan komponen IPS: objectives (return/risk) + 5 constraints.', 'Membedakan kebutuhan private wealth vs 4 tipe institusi.', 'Menjelaskan tax-loss harvesting dan asset location.', 'Menyusun IPS 1 halaman dari profil klien.'], 'story_title': 'Cerita: Warisan yang Habis Dimakan Pajak', 'story': "<p><strong>Pak Darma</strong> mewarisi portofolio saham <strong>Rp5 miliar</strong>. Manajernya aktif trading: return bruto <strong>18%/tahun</strong> — mengagumkan! Lima tahun kemudian, Pak Darma hitung: <strong>return bersih setelah pajak cuma 11%</strong>. Rekan yang buy-and-hold indeks (12% bruto) dapat <strong>11,5% bersih</strong>.</p>\n<p>Twist-nya: <strong>trading aktif = pajak tahunan</strong> atas tiap keuntungan (realisasi!), sementara buy-and-hold <strong>menunda pajak</strong> (unrealized tidak kena). Manajer 'hebat' kalah dari strategi 'malas' — <strong>setelah pajak</strong>. <strong>Return yang penting = yang bisa dibelanjakan.</strong> Lesson ini: IPS yang sadar pajak.</p>", 'concepts': [{'id': 'ips', 'toc': 'Anatomi IPS', 'title': 'IPS — Kontrak Sebelum Perang', 'body': '<p><strong>Definisi.</strong> <strong>IPS</strong> = dokumen hidup berisi: <strong>Objectives</strong> — <em>return</em> (target terukur, real/nominal, bruto/neto) &amp; <em>risk tolerance</em> (kemampuan vs kemauan!). <strong>Constraints</strong> — <em>liquidity</em> (kebutuhan kas), <em>horizon</em>, <em>taxes</em>, <em>legal/regulatory</em>, <em>unique</em> (etika, agama, ESG).</p>\n<p><strong>Kemampuan vs kemauan</strong>: muda+horizon panjang = <em>mampu</em> ambil risiko; tapi jika panik saat −20% = <em>tidak mau</em> → ikuti yang <strong>lebih rendah</strong> (edukasi dulu!).</p>', 'formulas': [], 'intuisi': "IPS seperti <strong>resep + alergi pasien</strong>: return objective = 'sembuhkan penyakit ini'; risk tolerance = 'dosis maksimal yang kuat'; constraints = 'alergi &amp; pantangan'. Dokter (advisor) yang meresep tanpa tanya alergi = malpraktik.", 'kapan': 'Awal setiap relasi; review tahunan atau saat life event.', 'worked': {'title': '📐 Contoh: IPS Pak Darma (klik untuk buka)', 'body': '<p><strong>Return</strong>: 12% nominal bersih pajak (pendidikan anak 10 thn). <strong>Risk</strong>: kemampuan tinggi (horizon 15 thn), kemauan moderat → <strong>moderat</strong> (vol target &lt; 14%).</p>\n<p><strong>Constraints</strong>: likuiditas Rp200jt/thn; horizon 15 thn; <strong>pajak: minimalkan realisasi</strong> (tax-aware!); legal: —; unique: tidak untuk trading harian.</p>\n<p><strong>Implikasi</strong>: strategi <strong>buy-and-hold + tax-loss harvesting</strong>, bukan trading aktif. IPS ini <em>melarang</em> manajer lama beroperasi!</p>'}, 'charts': []}, {'id': 'institusi', 'toc': 'Wealth vs Institusi', 'title': 'Private Wealth vs Institusi — Beda Spesies', 'body': '<p><strong>Definisi.</strong> <strong>Private wealth</strong>: individu — pajak personal, horizon = umur, bias behavioral kuat, likuiditas personal. <strong>Institusi</strong>: (1) <strong>DB pension</strong> — bayar manfaat pasti → <strong>LDI</strong> (cocokkan aset-liabilitas!); (2) <strong>Endowment/yayasan</strong> — horizon abadi, spending rule (~5%); (3) <strong>Asuransi</strong> — liabilitas + regulasi ketat (RBC); (4) <strong>Bank/SWF</strong> — likuiditas &amp; regulasi.</p>\n<p><strong>Risk objective institusi</strong> sering = <strong>funded status</strong> (aset/liabilitas), bukan volatilitas absolut!</p>', 'formulas': [{'math': '\\text{Funded Ratio} = \\frac{\\text{Aset}}{PV(\\text{Liabilitas})}', 'symbols': ['DB pension: target funded ratio ≥ 100% (surplus)', 'Defisit → kontribusi naik / manfaat turun (politik!)', 'LDI: aset bergerak SEARAH liabilitas (duration match!)']}], 'intuisi': 'Institusi seperti <strong>kebun binatang</strong>: tiap hewan (pension, endowment, asuransi) punya <em>makanan</em> (liabilitas) &amp; <em>kandang</em> (regulasi) berbeda. Memberi makan singa dengan rumput (strategi salah spesies) = bencana.', 'kapan': 'Kelola/menganalisis dana institusi: pahami liabilitasnya dulu.', 'worked': {'title': '📐 Contoh: Dana pensiun defisit (klik untuk buka)', 'body': "<p>Dana pensiun: aset Rp800M, PV liabilitas Rp1.000M → <strong>funded 80%</strong> (defisit Rp200M).</p>\n<p><strong>Godaan</strong>: kejar return dengan saham 90% ('tutup defisit'). <strong>Bahaya</strong>: jika pasar jatuh, defisit <em>melebar</em> (aset turun, liabilitas naik saat rate turun!).</p>\n<p><strong>LDI</strong>: geser ke obligasi long-duration yang <strong>match liabilitas</strong> → funded ratio <em>stabil</em>, lalu tutup defisit via <strong>kontribusi</strong> bertahap. Membosankan tapi benar.</p>"}, 'charts': [{'data': '[{x: ["Private<br>wealth", "DB<br>pension", "Endowment", "Asuransi"], y: [15, 30, 99, 10], type: "bar", marker: {color: ["#2a7de1","#e8a838","#16a34a","#94a3b8"]}, text: ["15 thn","30 thn","∞","10 thn"], textposition: "outside"}]', 'title': 'Horizon khas tiap investor (tahun)', 'layout': '{xaxis: {title: "Investor"}, yaxis: {title: "Horizon (tahun)"}, showlegend: false}', 'cara': 'Tinggi batang = horizon investasi khas.', 'interpretasi': 'Endowment <strong>abadi</strong> → bisa illikuid (PE, infra). Asuransi <strong>pendek + regulasi</strong> → konservatif. Horizon menentukan <em>semesta aset yang boleh dimasuki</em> — private wealth 15 tahun ≠ pension 30 tahun.'}]}, {'id': 'pajak', 'toc': 'Tax-Aware Investing', 'title': 'Pajak — Return yang Bisa Dibelanjakan', 'body': '<p><strong>Definisi.</strong> <strong>Tax-loss harvesting</strong>: jual posisi rugi untuk <em>mengakui</em> kerugian → offset keuntungan (kurangi pajak), lalu beli kembali aset <em>sejenis</em> (waspadai <em>wash sale</em>!). <strong>Asset location</strong>: taruh aset <em>tidak efisien pajak</em> (obligasi, REIT) di akun <strong>pensiun</strong> (tax-deferred), aset efisien (saham growth) di akun <strong>kena pajak</strong>.</p>\n<p><strong>Prinsip</strong>: tunda realisasi keuntungan (unrealized tidak kena pajak); percepat realisasi kerugian.</p>', 'formulas': [], 'intuisi': "Tax-loss harvesting seperti <strong>panen 'rugi' untuk pupuk</strong>: tanaman yang layu (posisi rugi) dicabut — 'pupuknya' (pengurang pajak) menyuburkan kebun. Asset location seperti <strong>menaruh es di freezer, bukan di teras</strong>: aset 'bocor pajak' di akun terlindung.", 'kapan': 'Akun kena pajak: panen rugi tiap akhir tahun; alokasi akun saat setup.', 'worked': {'title': '📐 Contoh: Panen Pak Darma (klik untuk buka)', 'body': '<p>Portofolio: saham A untung Rp500jt (unrealized), saham B rugi Rp200jt. Tarif pajak capital gain 20%.</p>\n<p><strong>Tanpa harvesting</strong>: jual A → pajak 20%×500 = <strong>Rp100jt</strong>.</p>\n<p><strong>Dengan harvesting</strong>: jual B juga → net gain 300 → pajak <strong>Rp60jt</strong>. <strong>Hemat Rp40jt!</strong> Beli kembali saham sejenis B (jaga exposure).</p>\n<p><strong>Wash sale</strong>: jangan beli kembali <em>identik</em> dalam 30 hari (aturan US; prinsip kehati-hatian umum).</p>'}, 'charts': []}], 'myths': [{'t': 'Return bruto 18% selalu lebih baik dari 12%. Pilih manajer return tertinggi.', 'benar': 'Pak Darma: 18% bruto → <strong>11% neto</strong> (trading = pajak tahunan); 12% buy-and-hold → <strong>11,5% neto</strong>. <strong>Tax drag</strong> bisa 2–7% poin untuk strategi aktif! Bandingkan <strong>setelah pajak &amp; biaya</strong> — itulah yang dibelanjakan.'}, {'t': 'IPS = formalitas sekali tulis, simpan di laci.', 'benar': "IPS = <strong>dokumen hidup</strong>: review tahunan + saat life event (nikah, warisan, PHK). IPS Pak Darma <em>melarang</em> gaya manajer lama — tanpa IPS, manajer 'hebat' itu terus menggerogoti pajak. IPS = <strong>rem</strong> atas godaan."}], 'tips': ["<strong>Selalu tanya 'setelah pajak?'</strong> Setiap pitch manajer/produk: minta return <em>setelah pajak &amp; biaya</em>. Jika tidak bisa memberi — itu jawabannya.", '<strong>Panen rugi tiap Desember.</strong> Jadwalkan review tax-loss harvesting akhir tahun: daftar posisi rugi → putuskan panen vs tahan (jangan panen buta — pertimbangkan prospek!).'], 'labs': [{'heading': 'Generator IPS 1 Halaman', 'intro': 'Jawab 6 pertanyaan — dapatkan draf IPS terstruktur.', 'title': 'Lab 1 — Generator IPS', 'hint': 'Ubah HORIZON 15 → 3 (butuh dana segera). Lihat risk & alokasi berubah drastis!', 'code': '# Generator IPS 1 halaman\nNAMA = "Pak Darma"\nTUJUAN = "Pendidikan anak"\nHORIZON = 15        # tahun (ubah!)\nKEMAMPUAN = "tinggi"  # tinggi/sedang/rendah\nKEMAUAN = "moderat"   # agresif/moderat/konservatif\nLIKUIDITAS_THN = 200  # Rp jt/tahun\nPAJAK_SADAR = True\n\nrisk = min(KEMAMPUAN, KEMAUAN, key=["rendah","konservatif","moderat","sedang","tinggi","agresif"].index)\nprint(f"IPS {NAMA} - Tujuan: {TUJUAN}")\nprint(f"  Return objective : {12 if HORIZON>10 else 6}% nominal bersih pajak")\nprint(f"  Risk tolerance   : {risk} (kemampuan {KEMAMPUAN}, kemauan {KEMAUAN})")\nprint(f"  Horizon          : {HORIZON} tahun")\nprint(f"  Likuiditas       : Rp{LIKUIDITAS_THN}jt/tahun")\nprint(f"  Pajak            : {\'tax-aware (tunda realisasi, panen rugi)\' if PAJAK_SADAR else \'standar\'}")\nprint(f"  Review           : tahunan + life event")\nprint("\\nAturan: ikuti risk TERENDAH dari kemampuan vs kemauan.")\n'}, {'heading': 'Kalkulator Tax-Loss Harvesting', 'intro': 'Hitung penghematan pajak dari memanen kerugian.', 'title': 'Lab 2 — Kalkulator Tax Harvesting', 'hint': 'Ubah RUGI_B 200 → 500 (panen lebih besar). Pajak makin kecil — tapi jangan panen aset bagus buta!', 'code': '# Tax-loss harvesting\nUNTUNG_A = 500   # Rp jt unrealized gain saham A\nRUGI_B = 200     # Rp jt unrealized loss saham B (ubah!)\nTARIF = 0.20\n\npajak_tanpa = UNTUNG_A * TARIF\nnet_gain = max(0, UNTUNG_A - RUGI_B)\npajak_dengan = net_gain * TARIF\nhemat = pajak_tanpa - pajak_dengan\n\nprint(f"Jual A saja: pajak Rp{pajak_tanpa:.0f}jt")\nprint(f"Jual A + panen B: pajak Rp{pajak_dengan:.0f}jt")\nprint(f"HEMAT: Rp{hemat:.0f}jt ({hemat/pajak_tanpa:.0%} dari pajak!)")\nprint()\nprint("Ingat: beli kembali eksposur sejenis (jaga alokasi),")\nprint("waspadai wash sale (jangan beli identik < 30 hari).")\n'}], 'decisions': [{'kondisi': 'Klien baru', 'pakai': 'IPS tertulis sebelum produk', 'alasan': 'Diagnosis sebelum resep.', 'contoh': 'Generator Lab 1.'}, {'kondisi': 'Kemampuan tinggi, kemauan rendah', 'pakai': 'Ikuti kemauan (edukasi bertahap)', 'alasan': 'Risiko yang tidak bisa ditahan = risiko yang merugikan.', 'contoh': 'Mulai moderat, naikkan pelan.'}, {'kondisi': 'Akun kena pajak + posisi rugi', 'pakai': 'Tax-loss harvesting (Desember)', 'alasan': 'Ubah rugi jadi pengurang pajak.', 'contoh': 'Panen Rp200jt → hemat Rp40jt.'}, {'kondisi': 'Alokasi antar-akun', 'pakai': 'Asset location: tidak efisien → tax-deferred', 'alasan': 'Obligasi/REIT di pensiun; growth di kena pajak.', 'contoh': 'Setup awal portofolio.'}], 'rule10': '<ol><li><strong>IPS dulu</strong>, produk kemudian.</li><li><strong>Ikuti risk terendah</strong> (mampu vs mau).</li><li><strong>Setelah pajak</strong> = yang dihitung.</li><li><strong>Panen rugi</strong>, tunda untung.</li></ol>', 'case': {'toc': 'Mini-Case: Pak Darma', 'title': 'Warisan Rp5M, Pajak Menggerogoti', 'body': '<p>Pak Darma: manajer trading 18% bruto → 11% neto (pajak tahunan). Alternatif buy-and-hold 12% → 11,5% neto.</p>', 'q': '(a) Mekanisme tax drag? (b) Susun IPS 1 paragraf. (c) Tiga aksi tax-aware tahun 1?', 'pembahasan': "<p>(a) <strong>Realisasi tahunan</strong> = pajak tahunan atas tiap gain (20%); compounding <em>setelah</em> pajak vs buy-and-hold yang compounding <em>penuh</em> lalu pajak sekali di akhir. Selisih 7 poin = <strong>biaya 'aktif'</strong>.</p>\n<p>(b) <strong>IPS</strong>: return 12% neto; risk moderat (vol &lt; 14%); horizon 15 thn; likuiditas Rp200jt/thn; <strong>tax-aware</strong> (minimalkan realisasi); review tahunan.</p>\n<p>(c) <strong>(1)</strong> Ganti ke strategi buy-and-hold; <strong>(2)</strong> asset location (obligasi → akun pensiun); <strong>(3)</strong> jadwal panen rugi Desember.</p>"}, 'quiz': [{'q': '18% bruto aktif vs 12% buy-and-hold. Setelah pajak (20% tahunan vs akhir)?', 'options': ['Aktif menang', 'Buy-and-hold menang (11,5% vs 11% neto)', 'Sama', 'Tidak bisa dihitung'], 'correct': 1, 'why': 'Benar: tax drag tahunan menggerogoti compounding. Bandingkan selalu setelah pajak & biaya.'}, {'q': 'Kemampuan tinggi, kemauan konservatif. Risk tolerance?', 'options': ['Tinggi', 'Konservatif (ikuti yang terendah + edukasi)', 'Moderat', 'Agresif'], 'correct': 1, 'why': 'Benar: risiko yang tidak bisa ditahan = panic selling. Ikuti kemauan, edukasi bertahap.'}, {'q': 'Untung Rp500jt, rugi Rp200jt, tarif 20%. Hemat via harvesting?', 'options': ['Rp0', 'Rp40jt', 'Rp100jt', 'Rp200jt'], 'correct': 1, 'why': "Benar: (500−200)×20% = 60 vs 500×20% = 100 → hemat 40. Rugi jadi 'pupuk' pajak."}, {'q': 'Dana pensiun DB defisit 80% funded. Strategi?', 'options': ['All-in saham kejar return', 'LDI: match durasi + kontribusi bertahap', 'Tarik semua', 'Abaikan'], 'correct': 1, 'why': 'Benar: kejar return saat defisit = risiko melebar (aset turun + liabilitas naik). LDI stabilkan funded ratio dulu.'}, {'q': 'Asset location yang benar?', 'options': ['Obligasi di akun kena pajak', 'Aset tidak efisien pajak (obligasi) di tax-deferred', 'Acak', 'Semua di satu akun'], 'correct': 1, 'why': "Benar: 'taruh es di freezer' — aset bocor pajak di akun terlindung; growth efisien di kena pajak."}], 'rangkum': ['<strong>IPS</strong>: objectives (return, risk: mampu vs mau) + constraints (likuiditas, horizon, pajak, legal, unique).', '<strong>Institusi</strong>: DB (LDI, funded ratio), endowment (abadi), asuransi (regulasi).', '<strong>Tax drag</strong>: realisasi tahunan membunuh compounding; bandingkan neto.', '<strong>Harvesting</strong>: panen rugi → offset gain; waspadai wash sale.', '<strong>Asset location</strong>: tidak efisien → tax-deferred.', '<strong>IPS hidup</strong>: review tahunan + life event.'], 'prev': ['pm-b9-intercorporate', 'PM-B9'], 'next': ['pm-c2-capital-market-expectations', 'PM-C2']}, {'slug': 'pm-c2-capital-market-expectations', 'id': 'PM-C2', 'track': 'Portfolio Management', 'title_html': 'Capital Market Expectations:<br/>Membaca Masa Depan', 'title_plain': 'Capital Market Expectations', 'chapter_summary': 'CFA L3: framework ekspektasi pasar modal — dari growth ekonomi ke return aset, Taylor rule, dekomposisi Grinold-Kroner, dan jebakan forecasting. Lab kalkulator Grinold-Kroner & Taylor rule.', 'tujuan': ['Menjelaskan rantai GDP → earnings → return saham.', 'Menghitung expected return via dekomposisi Grinold-Kroner.', 'Menjelaskan Taylor rule dan sinyalnya.', 'Mengidentifikasi bias dalam forecasting.'], 'story_title': "Cerita: Ramalan 'Pasti' 2020", 'story': "<p><strong>Desember 2019</strong>: konsensus analis — <em>&ldquo;2020: growth stabil, saham +8%.&rdquo;</em> <strong>Maret 2020</strong>: COVID — pasar <strong>−35%</strong> dalam sebulan. <strong>Desember 2020</strong>: pasar <strong>+16%</strong> setahun. <em>Semua</em> ramalan salah — dua kali.</p>\n<p>Twist-nya: yang salah bukan <em>framework</em>-nya, melainkan <strong>ekspektasi presisi</strong>. CME yang benar = <strong>rentang skenario + probabilitas</strong>, bukan angka tunggal. Peramal 2019 yang berkata '+8% ± 25%' = <strong>jujur</strong>; yang berkata '+8%' = <strong>bohong presisi</strong>. Lesson ini: ekspektasi yang rendah hati.</p>", 'concepts': [{'id': 'framework', 'toc': 'Framework CME', 'title': 'Framework — Dari Ekonomi ke Return', 'body': '<p><strong>Definisi.</strong> <strong>CME</strong> = ekspektasi return/risiko/korelasi <em>jangka panjang</em> (10+ tahun) per kelas aset. <strong>Rantai</strong>: GDP riil → <strong>earnings growth</strong> (≈ GDP + inflasi, jangka panjang) → <strong>return saham</strong> = yield dividen + growth + Δvaluasi. <strong>Obligasi</strong>: yield awal ≈ return ekspektasi (prediktor terbaik!).</p>\n<p><strong>Aturan praktis</strong>: expected return obligasi ≈ <strong>YTM kini</strong>; saham via <strong>Grinold-Kroner</strong>.</p>', 'formulas': [{'math': 'E(R) \\approx DY + g + \\Delta PE', 'symbols': ['<Tex math={String.raw`DY`} />: dividend yield kini', '<Tex math={String.raw`g`} />: growth earnings/dividen riil (≈ GDP riil jangka panjang)', '<Tex math={String.raw`\\Delta PE`} />: perubahan valuasi (→ 0 jangka panjang; jangan andalkan!)', 'Grinold-Kroner: + inflasi &amp; −/+ repurchase yield untuk total']}], 'intuisi': 'CME seperti <strong>prakiraan iklim, bukan cuaca</strong>: tidak menebak hujan besok (2020!), tapi tahu musim kemarau datang tiap tahun (siklus) &amp; suhu rata-rata naik (trend). Alokasi butuh <em>iklim</em>, bukan <em>cuaca</em>.', 'kapan': 'SAA (PM-C3): input expected return tiap kelas aset.', 'worked': {'title': '📐 Contoh: Ekspektasi IHSG (klik untuk buka)', 'body': '<p>DY = 2,5%, g riil = 5% (GDP), inflasi 3%, ΔPE = 0 (asumsi netral).</p>\n<p><strong>E(R) nominal</strong> ≈ 2,5% + 5% + 3% = <strong>10,5%</strong>.</p>\n<p>Jika pasar kini P/E 20 (mahal, mean-revert ke 15 dalam 10 thn): ΔPE ≈ −2,8%/thn → E(R) ≈ <strong>7,7%</strong>. <strong>Valuasi awal menentukan separuh ekspektasi!</strong></p>'}, 'charts': []}, {'id': 'taylor', 'toc': 'Taylor Rule & Sinyal', 'title': 'Taylor Rule — Membaca Bank Sentral', 'body': "<p><strong>Definisi.</strong> <strong>Taylor rule</strong>: i = r* + π + 0,5(π − π*) + 0,5(y − y*) — suku bunga 'wajar' dari inflasi &amp; output gap. <strong>Sinyal pasar</strong>: kurva yield (PM-B5), credit spread, VIX.</p>\n<p>Jika BI rate <em>di bawah</em> Taylor → <strong>longgar</strong> (mendukung aset risiko, waspada inflasi); <em>di atas</em> → <strong>ketat</strong>.</p>", 'formulas': [{'math': 'i = r^* + \\pi + 0{,}5(\\pi - \\pi^*) + 0{,}5(y - y^*)', 'symbols': ['<Tex math={String.raw`r^*`} />: real rate netral (≈ 1–2%)', '<Tex math={String.raw`\\pi^*`} />: target inflasi', '<Tex math={String.raw`y-y^*`} />: output gap (ekonomi di atas/di bawah potensial)', 'Rule of thumb, bukan autopilot — bank sentral punya judgment']}], 'intuisi': "Taylor rule seperti <strong>resep masakan bank sentral</strong>: inflasi di atas target → tambah 'garam' (rate); ekonomi lesu → kurangi. Pasar menebak <em>masakan berikutnya</em> dari resep ini — surprise = volatilitas.", 'kapan': 'Antisipasi kebijakan moneter; positioning durasi.', 'worked': {'title': '📐 Contoh: BI rate wajar? (klik untuk buka)', 'body': '<p>r* = 2%, π = 4%, π* = 3%, output gap +1%.</p>\n<p><strong>i</strong> = 2 + 4 + 0,5(1) + 0,5(1) = <strong>7%</strong>.</p>\n<p>BI rate aktual 6% → <strong>longgar</strong> (1% di bawah rule) → dukung saham/properti, waspada rupiah. Jika inflasi → 6%: rule = 9% → <strong>ekspektasi kenaikan agresif</strong> → kurangi durasi!</p>'}, 'charts': [{'data': '[{x: ["2020","2021","2022","2023","2024"], y: [3.75,3.5,5.5,6.0,6.0], type: "scatter", mode: "lines+markers", marker: {color: "#2a7de1"}, name: "BI rate aktual"}, {x: ["2020","2021","2022","2023","2024"], y: [4.0,4.5,7.0,6.5,6.0], type: "scatter", mode: "lines+markers", marker: {color: "#e8a838"}, name: "Taylor rule (ilustrasi)"}]', 'title': 'BI rate vs Taylor rule (ilustrasi)', 'layout': '{xaxis: {title: "Tahun"}, yaxis: {title: "(%)"}, showlegend: true}', 'cara': 'Biru = aktual, kuning = rule. Selisih = stance kebijakan.', 'interpretasi': '2022: rule <strong>di atas</strong> aktual → tekanan menaikkan (terjadi!). 2024: konvergen → <strong>netral</strong>. Taylor bukan ramalan sempurna — tapi <strong>jangkar ekspektasi</strong> yang jujur. (Ilustrasi edukasi, bukan data resmi.)'}]}, {'id': 'bias', 'toc': 'Jebakan Forecasting', 'title': 'Jebakan — Mengapa Peramal Gagal', 'body': "<p><strong>Definisi.</strong> <strong>Bias peramal</strong>: <em>overconfidence</em> (rentang terlalu sempit), <em>anchoring</em> (terpaku data kini), <em>availability</em> (krisis terakhir mendominasi), <em>herding</em> (ikut konsensus aman).</p>\n<p><strong>Obat</strong>: <strong>skenario</strong> (base/bull/bear + probabilitas), <strong>pre-mortem</strong> ('bayangkan gagal — kenapa?'), <strong>base rate</strong> (sejarah kelas aset, bukan cerita).</p>", 'formulas': [], 'intuisi': 'Forecasting tanpa disiplin seperti <strong>meramal dengan bola kristal retak</strong>: yang terlihat = biasmu sendiri. Skenario + base rate = <strong>mengganti bola kristal dengan peta &amp; kompas</strong> — tetap bisa tersesat, tapi tahu di mana.', 'kapan': 'Setiap CME: paksa 3 skenario + probabilitas eksplisit.', 'worked': {'title': '📐 Contoh: Pre-mortem 2020 (klik untuk buka)', 'body': "<p><strong>Des 2019, pre-mortem</strong>: 'Bayangkan Des 2020 portofolio −30%. Kenapa?' → <em>pandemi? perang? krisis finansial?</em></p>\n<p><strong>Hasil</strong>: tim sadar <em>tidak ada</em> proteksi ekor → tambah <strong>5% protective put</strong> / kas. Maret 2020: −35% → portofolio −22% (put bekerja).</p>\n<p><strong>Pre-mortem 1 jam</strong> &gt; model 100 halaman. Murah, jujur, menyelamatkan.</p>"}, 'charts': []}], 'myths': [{'t': 'Konsensus analis (+8%) = ekspektasi terbaik. Ikuti saja.', 'benar': '2020: konsensus salah <strong>dua kali</strong> (±35%). Konsensus = <strong>herding</strong>, bukan kebijaksanaan. CME yang benar = <strong>distribusi</strong> (base/bull/bear + probabilitas), bukan titik. Titik tanpa rentang = bohong presisi.'}, {'t': "YTM obligasi tidak relevan untuk ekspektasi return — yang penting 'view'.", 'benar': "<strong>YTM kini adalah prediktor return obligasi 10-tahunan terbaik</strong> (R² ~90%!). Mengabaikannya demi 'view' = mengabaikan matematika. Untuk saham pakai Grinold-Kroner; untuk obligasi, <em>percaya YTM</em>."}], 'tips': ["<strong>Tulis ekspektasi sebagai rentang.</strong> 'Saham 8% ± 15%' jauh lebih berguna dari '8%'. Rentang memaksa sizing yang jujur (berapa rugi jika −1σ?).", '<strong>Pre-mortem tiap keputusan besar.</strong> 1 jam membayangkan kegagalan &gt; 1 minggu model optimis. Jadikan ritual komite investasi.'], 'labs': [{'heading': 'Kalkulator Grinold-Kroner', 'intro': 'Dekomposisi expected return saham: yield + growth + repricing.', 'title': 'Lab 1 — Kalkulator Grinold-Kroner', 'hint': 'Ubah REPRICING 0.0 → -0.028 (P/E mean-revert). Ekspektasi anjlok — valuasi awal menentukan!', 'code': '# Grinold-Kroner: E(R) = DY + g_riil + inflasi + repricing\nDY = 0.025        # dividend yield\nG_RIIL = 0.05     # growth riil (GDP)\nINFLASI = 0.03\nREPRICING = 0.0   # ubah! (-0.028 jika P/E mahal -> mean revert)\n\ner = DY + G_RIIL + INFLASI + REPRICING\nprint(f"E(R) nominal = {DY:.1%} + {G_RIIL:.0%} + {INFLASI:.0%} + ({REPRICING:.1%})")\nprint(f"           = {er:.1%}")\nprint()\nprint("Repricing -> 0 jangka panjang, tapi DOMINAN dalam 3-5 tahun.")\nprint("Jangan andalkan multiple expansion untuk ekspektasi!")\n'}, {'heading': 'Kalkulator Taylor Rule', 'intro': "Hitung suku bunga 'wajar' dan baca stance kebijakan.", 'title': 'Lab 2 — Kalkulator Taylor', 'hint': 'Ubah INFLASI 0.04 → 0.06. Rule melonjak — ekspektasi pengetatan agresif!', 'code': '# Taylor rule: i = r* + pi + 0.5*(pi - pi*) + 0.5*(gap)\nR_STAR, PI_STAR = 0.02, 0.03\nINFLASI, GAP = 0.04, 0.01   # ubah INFLASI!\nAKTUAL = 0.06               # BI rate kini\n\nrule = R_STAR + INFLASI + 0.5*(INFLASI - PI_STAR) + 0.5*GAP\nselisih = AKTUAL - rule\nprint(f"Taylor rule: {rule:.2%}")\nprint(f"Aktual     : {AKTUAL:.2%}")\nprint(f"Stance     : {\'KETAT\' if selisih > 0.005 else \'LONGGAR\' if selisih < -0.005 else \'NETRAL\'} ({selisih:+.2%})")\nprint()\nprint("Longgar -> dukung aset risiko; Ketat -> kurangi durasi.")\n'}], 'decisions': [{'kondisi': 'Menentukan E(R) obligasi', 'pakai': 'YTM kini', 'alasan': 'Prediktor 10-tahunan terbaik.', 'contoh': 'YTM 7% → E(R) ≈ 7%.'}, {'kondisi': 'Menentukan E(R) saham', 'pakai': 'Grinold-Kroner', 'alasan': 'Dekomposisi jujur.', 'contoh': 'DY+g+inflasi ± repricing.'}, {'kondisi': 'BI rate vs Taylor', 'pakai': 'Baca stance; antisipasi', 'alasan': 'Rule = jangkar ekspektasi.', 'contoh': 'Rule &gt; aktual → siaga naik.'}, {'kondisi': 'Keputusan alokasi besar', 'pakai': 'Pre-mortem + 3 skenario', 'alasan': 'Lawan overconfidence.', 'contoh': 'Ritual komite.'}], 'rule10': '<ol><li><strong>Iklim, bukan cuaca</strong> (10+ tahun).</li><li><strong>YTM</strong> untuk obligasi; <strong>GK</strong> untuk saham.</li><li><strong>Rentang + probabilitas</strong>, bukan titik.</li><li><strong>Pre-mortem</strong> selalu.</li></ol>', 'case': {'toc': 'Mini-Case: Ramalan 2020', 'title': 'Konsensus yang Salah Dua Kali', 'body': "<p>Des 2019: konsensus '+8%'. Mar 2020: −35%. Des 2020: +16% setahun.</p>", 'q': "(a) Apa yang salah dari '+8%'? (b) Format CME yang benar? (c) Aksi dari pre-mortem?", 'pembahasan': "<p>(a) <strong>Titik tanpa rentang</strong> = bohong presisi; herding konsensus. Realisasi ±35% = di luar 'model' siapa pun.</p>\n<p>(b) <strong>Base/bull/bear + probabilitas</strong> + rentang (±σ). '+8% ± 25%' = jujur &amp; berguna untuk sizing.</p>\n<p>(c) <strong>Proteksi ekor</strong> (put/kas 5%) dari pre-mortem — murah saat tenang, mahal saat dibutuhkan.</p>"}, 'quiz': [{'q': 'DY 2,5%, g riil 5%, inflasi 3%, repricing 0. E(R)?', 'options': ['7,5%', '10,5%', '5%', '13,5%'], 'correct': 1, 'why': 'Benar: 2,5+5+3 = 10,5%. Jika P/E mahal (mean-revert −2,8%) → 7,7%. Valuasi awal menentukan!'}, {'q': 'r*=2%, π=4%, π*=3%, gap=+1%. Taylor rule?', 'options': ['6%', '7%', '8%', '5%'], 'correct': 1, 'why': 'Benar: 2+4+0,5+0,5 = 7%. Aktual 6% → longgar → dukung risiko, waspada inflasi.'}, {'q': 'Prediktor return obligasi 10-tahunan terbaik?', 'options': ['View analis', 'YTM kini', 'Rating', 'Kupon'], 'correct': 1, 'why': 'Benar: YTM kini (R² ~90%). Matematika &gt; opini untuk obligasi.'}, {'q': 'Obat overconfidence dalam forecasting?', 'options': ['Model lebih kompleks', 'Skenario + pre-mortem + base rate', 'Ikut konsensus', 'Abaikan'], 'correct': 1, 'why': 'Benar: 3 skenario + probabilitas + pre-mortem 1 jam &gt; model 100 halaman.'}, {'q': 'Inversi kurva 2s10s sinyal?', 'options': ['Growth kuat', 'Risiko resesi (ekspektasi pemotongan rate)', 'Inflasi', 'Tidak ada'], 'correct': 1, 'why': 'Benar: pasar bertaruh rate turun = resesi datang. Timing 6–24 bulan.'}], 'rangkum': ['<strong>CME</strong>: ekspektasi 10+ tahun per kelas aset; rantai GDP → earnings → return.', '<strong>Grinold-Kroner</strong>: DY + g + inflasi ± repricing.', '<strong>Obligasi</strong>: YTM kini = prediktor terbaik.', '<strong>Taylor rule</strong>: jangkar ekspektasi kebijakan moneter.', '<strong>Format</strong>: skenario + probabilitas + rentang; pre-mortem ritual.', '<strong>Aturan</strong>: iklim bukan cuaca; titik tanpa rentang = bohong.'], 'prev': ['pm-c1-ips', 'PM-C1'], 'next': ['pm-c3-asset-allocation', 'PM-C3']}, {'slug': 'pm-c3-asset-allocation', 'id': 'PM-C3', 'track': 'Portfolio Management', 'title_html': 'Asset Allocation:<br/>SAA, TAA & LDI', 'title_plain': 'Asset Allocation: SAA, TAA, LDI, Factor-Based', 'chapter_summary': 'CFA L3 alokasi: strategic (SAA) via mean-variance, tactical tilts (TAA), liability-driven investing, dan alokasi berbasis faktor risiko. Lab frontier mean-variance & simulator funding ratio LDI.', 'tujuan': ['Menjelaskan SAA sebagai keputusan terpenting (Brinson).', 'Membedakan SAA vs TAA dan disiplin rebalancing.', 'Menjelaskan LDI: surplus optimization & funding ratio.', 'Menjelaskan alokasi berbasis faktor risiko.'], 'story_title': 'Cerita: 90% Return dari Satu Keputusan', 'story': '<p><strong>Brinson, Hood &amp; Beebower (1986)</strong>: studi legendaris — <strong>&gt;90% variasi return</strong> dana pensiun dijelaskan oleh <strong>alokasi aset</strong>, bukan stock picking atau market timing!</p>\n<p>Twist-nya: industri reksadana menghabiskan miliaran untuk <em>stock picking</em> (yang menjelaskan &lt;10%), sementara <strong>keputusan alokasi</strong> — saham vs obligasi vs kas — dibuat <em>asal-asalan</em> di banyak institusi. <strong>80% energi untuk 10% hasil.</strong> Lesson ini: memfokuskan energi ke yang paling menentukan.</p>', 'concepts': [{'id': 'saa', 'toc': 'SAA: Strategic', 'title': 'SAA — Keputusan 90%', 'body': '<p><strong>Definisi.</strong> <strong>SAA</strong> (<em>strategic asset allocation</em>): policy portfolio jangka panjang dari <strong>mean-variance optimization</strong> + constraints IPS. <strong>Efficient frontier</strong>: set portofolio return maksimal per risiko. <strong>TAA</strong>: tilt <em>taktis</em> jangka pendek menyimpang dari SAA (mis. overweight saham 5% saat murah) — dengan <strong>disiplin kembali</strong>.</p>\n<p><strong>Rebalancing</strong>: kembalikan ke SAA (calendar atau tolerance band) — <strong>jual mahal, beli murah</strong> otomatis.</p>', 'formulas': [{'math': '\\max_w \\ w^T\\mu - \\frac{\\lambda}{2}w^T\\Sigma w', 'symbols': ['<Tex math={String.raw`w`} />: bobot aset', '<Tex math={String.raw`\\mu, \\Sigma`} />: expected return &amp; kovarians (dari CME, PM-C2!)', '<Tex math={String.raw`\\lambda`} />: risk aversion (dari IPS, PM-C1!)', 'Rantai: IPS → CME → optimisasi → SAA. Putus satu = asal-asalan.']}], 'intuisi': 'SAA seperti <strong>resep diet jangka panjang</strong>: komposisi makronutrien (saham/obligasi) menentukan 90% kesehatan. TAA = <strong>cheat meal terencana</strong> sesekali — boleh, asal kembali ke resep. Tanpa resep = diet yo-yo.', 'kapan': 'Setiap penetapan kebijakan investasi; review 3–5 tahunan.', 'worked': {'title': '📐 Contoh: SAA pensiun (klik untuk buka)', 'body': '<p>IPS: return 8%, vol &lt; 12%. CME: saham E(R) 10,5% σ 18%; obligasi 7% σ 6%; ρ = 0,2.</p>\n<p><strong>60/40</strong>: E(R) = 9,1%, σ = √(0,36×0,0324 + 0,16×0,0036 + 2×0,6×0,4×0,2×0,18×0,06) = √(0,0117+0,0006+0,0010) = <strong>11,5%</strong> ✓.</p>\n<p><strong>TAA</strong>: saham murah (P/E −1σ) → tilt 65/35 sementara; <strong>rebalance</strong> saat kembali normal. Disiplin = kunci.</p>'}, 'charts': [{'data': '[{x: [6,8,11.5,14,18], y: [7,8.2,9.1,9.8,10.5], type: "scatter", mode: "lines+markers", marker: {color: "#2a7de1"}, name: "frontier"}, {x: [11.5], y: [9.1], type: "scatter", mode: "markers", marker: {color: "#ef4444", size: 12}, name: "SAA 60/40"}]', 'title': 'Efficient frontier (ilustrasi): risiko vs return', 'layout': '{xaxis: {title: "Volatilitas (%)"}, yaxis: {title: "Expected return (%)"}, showlegend: true}', 'cara': 'Kurva biru = frontier; titik merah = SAA 60/40 terpilih.', 'interpretasi': 'Titik <strong>di bawah</strong> kurva = tidak efisien (risiko sama, return kurang). SAA dipilih <strong>di</strong> kurva sesuai batas IPS (vol &lt; 12%). Optimisasi tanpa constraints IPS = <strong>jawaban matematis untuk pertanyaan yang salah</strong>.'}]}, {'id': 'ldi', 'toc': 'LDI', 'title': 'LDI — Investasi untuk Membayar Janji', 'body': '<p><strong>Definisi.</strong> <strong>LDI</strong> (<em>liability-driven investing</em>): tujuan = <strong>funded ratio stabil/naik</strong>, bukan return absolut. <strong>Surplus optimization</strong>: optimasi <em>surplus</em> (aset − liabilitas). <strong>Hedge portfolio</strong> (obligasi long-duration, match liabilitas) + <strong>growth portfolio</strong> (tutup defisit).</p>\n<p><strong>Glide path</strong>: makin funded → makin hedge (de-risking otomatis).</p>', 'formulas': [], 'intuisi': "LDI seperti <strong>menabung untuk cicilan rumah</strong>: bukan 'return maksimal', tapi 'pasti bisa bayar tiap bulan'. Hedge portfolio = <strong>autodebet</strong> (pasti cocok); growth = <strong>lembur</strong> (tutup kekurangan).", 'kapan': 'DB pension, asuransi — semua yang punya liabilitas pasti.', 'worked': {'title': '📐 Contoh: Dua portfolio (klik untuk buka)', 'body': '<p>Dana defisit 80%: <strong>hedge 50%</strong> (D=15) + <strong>growth 50%</strong> (D≈2) → D_aset = <strong>8,5</strong>.</p>\n<p>Rate turun 1%: liabilitas <strong>+15%</strong>, aset +8,5% → funded <strong>75%</strong> (vs <strong>71%</strong> tanpa hedge!). Hedge <em>penuh</em> (D_aset=15) → funded <strong>tetap 80%</strong> ✓.</p>\n<p><strong>LDI = asuransi funded ratio</strong>: makin besar hedge, makin stabil — tapi makin kecil growth untuk tutup defisit. <strong>Trade-off!</strong></p>'}, 'charts': []}, {'id': 'faktor', 'toc': 'Berbasis Faktor', 'title': 'Factor-Based — Alokasi DNA', 'body': '<p><strong>Definisi.</strong> <strong>Alokasi faktor</strong>: alokasikan ke <em>risiko premi</em> (equity, duration, credit, commodity) bukan ke <em>label aset</em>. <strong>60/40 saham/obligasi</strong> = <strong>90% risiko dari ekuitas</strong>! (saham jauh lebih volatile). <strong>Risk parity</strong> (pratinjau PM-D2): samakan kontribusi risiko.</p>\n<p><strong>Manfaat</strong>: diversifikasi <em>risiko</em> sejati, bukan diversifikasi <em>label</em>.</p>', 'formulas': [], 'intuisi': 'Alokasi tradisional seperti <strong>diet by warna makanan</strong> (60% merah, 40% hijau) — warnanya beda, nutrisinya bisa sama! Alokasi faktor = <strong>diet by nutrisi</strong> (protein, serat, vitamin) — yang benar-benar dibutuhkan tubuh (portofolio).', 'kapan': "Institusi canggih; saat 'diversifikasi' tradisional gagal (2008).", 'worked': {'title': '📐 Contoh: Bedah 60/40 (klik untuk buka)', 'body': "<p>Saham σ 18%, obligasi σ 6%, ρ 0,2. <strong>Kontribusi risiko</strong> saham ≈ <strong>88%</strong>!</p>\n<p>'Seimbang' 60/40 = <strong>taruhan ekuitas berkedok diversifikasi</strong>. 2008: −22%.</p>\n<p><strong>Risk parity</strong>: bobot by 1/σ → ~25/75 → kontribusi 50/50 → 2008: <strong>−8%</strong>. Bukan return lebih tinggi — <strong>risiko lebih jujur</strong>.</p>"}, 'charts': []}], 'myths': [{'t': 'Stock picking menentukan hasil. Fokus cari saham terbaik.', 'benar': 'Brinson: <strong>&gt;90% variasi return</strong> = alokasi aset. Energi industri terbalik: 80% untuk stock picking (10% hasil). <strong>Alokasi dulu, seleksi kemudian.</strong> Manajer hebat di alokasi salah = sia-sia.'}, {'t': '60/40 = portofolio seimbang dan terdiversifikasi.', 'benar': "<strong>88% risikonya dari saham!</strong> 'Seimbang' hanya di label, tidak di risiko. 2008 membuktikan: diversifikasi label ≠ diversifikasi risiko. Ukur <strong>kontribusi risiko</strong>, bukan bobot nominal."}], 'tips': ["<strong>Tulis policy portfolio dengan rentang, bukan titik.</strong> 'Saham 55–65%' + tolerance band = disiplin rebalancing otomatis. Titik kaku = trading emosional.", "<strong>Rebalancing = satu-satunya 'market timing' yang terbukti.</strong> Jual yang naik (mahal), beli yang turun (murah) — mekanis, tanpa prediksi. Jadwalkan, jangan rasakan."], 'labs': [{'heading': 'Kalkulator Frontier 2 Aset', 'intro': 'Hitung E(R) & risiko portofolio untuk berbagai bobot — temukan SAA.', 'title': 'Lab 1 — Kalkulator Frontier', 'hint': "Ubah RHO 0.2 → 0.8. Frontier 'menggembung' — diversifikasi berkurang!", 'code': '# Frontier 2 aset: cari SAA yang memenuhi IPS\nimport math\nER_S, SIG_S = 0.105, 0.18\nER_B, SIG_B = 0.07, 0.06\nRHO = 0.2   # ubah!\nTARGET_VOL = 0.12  # batas IPS\n\nprint(f"{\'saham\':>6} {\'E(R)\':>7} {\'vol\':>7}  IPS?")\nterbaik = None\nfor i in range(0, 101, 10):\n    w = i/100\n    er = w*ER_S + (1-w)*ER_B\n    var = w**2*SIG_S**2 + (1-w)**2*SIG_B**2 + 2*w*(1-w)*RHO*SIG_S*SIG_B\n    vol = math.sqrt(var)\n    ok = vol <= TARGET_VOL\n    print(f"{w:>6.0%} {er:>6.1%} {vol:>6.1%}  {\'OK\' if ok else \'\'}")\n    if ok and (terbaik is None or er > terbaik[1]): terbaik = (w, er)\nprint(f"\\nSAA terbaik (vol<={TARGET_VOL:.0%}): saham {terbaik[0]:.0%}, E(R) {terbaik[1]:.1%}")\n'}, {'heading': 'Simulator Funding Ratio LDI', 'intro': 'Simulasikan funded ratio dengan & tanpa hedge saat rate berubah.', 'title': 'Lab 2 — Simulator LDI', 'hint': 'Ubah D_RATE -0.01 → +0.01 (rate naik). Lihat efek ke funded ratio!', 'code': '# LDI: funded ratio dengan vs tanpa hedge\nASET, LIAB = 800, 1000  # Rp M\nD_LIAB = 15             # duration liabilitas\nD_HEDGE, W_HEDGE = 15, 0.5   # duration & bobot hedge portfolio\nD_RATE = -0.01          # perubahan yield (ubah!)\n\ndef funded(d_hedge_w):\n    d_aset = d_hedge_w*D_HEDGE + (1-d_hedge_w)*2  # growth durasi ~2\n    aset2 = ASET*(1 - d_aset*D_RATE)\n    liab2 = LIAB*(1 - D_LIAB*D_RATE)\n    return aset2/liab2\n\nprint(f"Funded awal: {ASET/LIAB:.0%}")\nprint(f"Tanpa hedge (w=0) : {funded(0):.0%}")\nprint(f"Dengan hedge (w=0.5): {funded(W_HEDGE):.0%}")\nprint("\\nRate turun: liabilitas meledak. Hedge = penyeimbang.")\nprint("LDI = stabilkan funded ratio, bukan kejar return.")\n'}], 'decisions': [{'kondisi': 'Menetapkan kebijakan investasi', 'pakai': 'SAA via optimisasi + constraints IPS', 'alasan': '90% penentu hasil.', 'contoh': '60/40 by IPS, bukan ikut-ikutan.'}, {'kondisi': 'Valuasi ekstrem (P/E ±1σ)', 'pakai': 'TAA tilt ±5% + disiplin kembali', 'alasan': 'Tilt terukur, bukan timing liar.', 'contoh': 'Overweight saham saat murah.'}, {'kondisi': 'Ada liabilitas pasti (pensiun)', 'pakai': 'LDI: hedge + growth', 'alasan': 'Funded ratio = objective.', 'contoh': 'Duration match.'}, {'kondisi': "'Diversifikasi' tapi 2008 hancur", 'pakai': 'Cek kontribusi risiko / factor-based', 'alasan': 'Label ≠ risiko.', 'contoh': 'Risk parity.'}], 'rule10': '<ol><li><strong>Alokasi = 90%</strong> penentu.</li><li><strong>SAA + disiplin TAA</strong>.</li><li><strong>Rebalancing mekanis</strong>.</li><li><strong>Ukur risiko</strong>, bukan bobot.</li></ol>', 'case': {'toc': 'Mini-Case: Brinson', 'title': '90% dari Satu Keputusan', 'body': '<p>Dana pensiun: return 8%/thn. Atribusi Brinson: alokasi menjelaskan 92% variasi. Tim habiskan 80% waktu untuk stock picking.</p>', 'q': '(a) Implikasi Brinson? (b) Realokasi energi tim? (c) Desain governance-nya?', 'pembahasan': '<p>(a) <strong>Alokasi &gt;&gt; seleksi.</strong> Stock picking hebat tidak menyelamatkan alokasi buruk.</p>\n<p>(b) <strong>60% energi</strong>: SAA/IPS/CME + rebalancing disiplin; <strong>30%</strong>: manajer &amp; biaya; <strong>10%</strong>: stock picking.</p>\n<p>(c) <strong>Komite alokasi</strong> terpisah dari komite seleksi; <strong>policy band</strong> tertulis; review SAA 3-tahunan. Struktur mengikuti <em>di mana</em> nilai diciptakan.</p>'}, 'quiz': [{'q': 'Studi Brinson: alokasi menjelaskan?', 'options': ['Kurang dari 10%', 'Lebih dari 90% variasi return', '50%', 'Tidak ada'], 'correct': 1, 'why': 'Benar: &gt;90%. Implikasi: fokus energi ke SAA/IPS/CME, bukan stock picking.'}, {'q': '60/40 saham/obligasi. Kontribusi risiko saham?', 'options': ['60%', '≈ 88% — taruhan ekuitas berkedok', '40%', '50%'], 'correct': 1, 'why': "Benar: saham jauh lebih volatile. 'Seimbang' di label ≠ seimbang di risiko."}, {'q': 'Rate turun 1%, liabilitas duration 15. Tanpa hedge, funded 80% jadi?', 'options': ['80%', '≈ 72% (liabilitas +15%, aset +5%)', '90%', '100%'], 'correct': 1, 'why': 'Benar: mismatch durasi = funded ratio ambruk saat rate turun. LDI hedge mencegah ini.'}, {'q': 'TAA yang disiplin?', 'options': ['Timing liar', 'Tilt ±5% saat valuasi ekstrem + kembali ke SAA', 'Tidak pernah menyimpang', 'Ikut tren'], 'correct': 1, 'why': 'Benar: TAA = deviasi terukur & sementara dari SAA. Tanpa disiplin kembali = drift.'}, {'q': 'Rebalancing otomatis = ?', 'options': ['Market timing', 'Jual mahal-beli murah mekanis', 'Tidak ada gunanya', 'Biaya sia-sia'], 'correct': 1, 'why': 'Benar: tolerance band menjual outperformer (mahal) & membeli underperformer (murah) — contrarian otomatis.'}], 'rangkum': ['<strong>SAA</strong>: policy portfolio dari IPS+CME+optimisasi; <strong>90% penentu</strong>.', '<strong>TAA</strong>: tilt taktis ±5% + disiplin kembali.', '<strong>LDI</strong>: funded ratio = objective; hedge + growth; glide path.', '<strong>Factor-based</strong>: alokasi risiko premi, bukan label; 60/40 = 88% risiko ekuitas.', '<strong>Rebalancing</strong>: mekanis, contrarian otomatis.', '<strong>Aturan</strong>: ukur kontribusi risiko; review SAA 3–5 tahun.'], 'prev': ['pm-c2-capital-market-expectations', 'PM-C2'], 'next': ['pm-c4-portfolio-construction', 'PM-C4']}, {'slug': 'pm-c4-portfolio-construction', 'id': 'PM-C4', 'track': 'Portfolio Management', 'title_html': 'Portfolio Construction:<br/>Optimisasi & Rebalancing', 'title_plain': 'Portfolio Construction: Optimisasi, Risk Budgeting, Rebalancing', 'chapter_summary': 'CFA L3 konstruksi: mean-variance dengan constraints praktis, risk budgeting & risk parity, serta rebalancing — calendar vs tolerance band, drift monitoring, dan biaya. Lab kalkulator risk contribution & simulator rebalancing.', 'tujuan': ['Menjelaskan optimisasi mean-variance dengan constraints realistis.', 'Menghitung risk contribution dan menjelaskan risk parity.', 'Membedakan calendar vs tolerance-band rebalancing.', 'Menjelaskan trade-off rebalancing: disiplin vs biaya.'], 'story_title': "Cerita: Portofolio yang 'Berjalan Sendiri'", 'story': "<p><strong>Yayasan</strong> menetapkan SAA <strong>60/40</strong> (2020). Tidak pernah rebalance. <strong>2024</strong>: saham bull run → portofolio jadi <strong>78/22</strong>. Lalu koreksi <strong>−15%</strong> — kerugian <strong>Rp2,7M lebih besar</strong> dari jika tetap 60/40.</p>\n<p>Twist-nya: <strong>tidak ada yang 'salah beli'</strong> — portofolio <em>berjalan sendiri</em> (drift) keluar dari IPS. <strong>Drift = keputusan pasif</strong> untuk mengambil risiko lebih. Rebalancing bukan 'trading' — melainkan <strong>kembali ke janji</strong>. Lesson ini: disiplin konstruksi.</p>", 'concepts': [{'id': 'optimisasi', 'toc': 'Optimisasi + Constraints', 'title': 'Optimisasi — Matematika Bertemu Realita', 'body': '<p><strong>Definisi.</strong> <strong>Mean-variance</strong>: max return per risiko (PM-C3). <strong>Constraints praktis</strong>: <em>long-only</em> (w ≥ 0), <em>max position</em> (w ≤ 10%), <em>turnover</em> (≤ 20%/thn), <em>tracking error</em> (≤ 3%), <em>sektor</em>, <em>ESG</em>. <strong>Black-Litterman</strong> (pratinjau PM-D2): campur <em>market equilibrium</em> + <em>view</em> analis.</p>\n<p><strong>Masalah</strong>: optimisasi <strong>sensitif ke input</strong> (error maximization!) → constraints = <strong>penjinak</strong>.</p>', 'formulas': [], 'intuisi': "Optimisasi tanpa constraints seperti <strong>GPS tanpa rambu</strong>: rute 'tercepat' bisa lewat gang sempit &amp; jembatan rusak (portofolio ekstrem 95% satu aset). Constraints = <strong>rambu &amp; batas kecepatan</strong> — sedikit lebih lambat, jauh lebih selamat.", 'kapan': 'Konstruksi: selalu dengan constraints; waspadai error maximization.', 'worked': {'title': '📐 Contoh: Error maximization (klik untuk buka)', 'body': '<p>Input: saham A E(R) 10,1%, B 10,0% (estimasi ±2%!). Optimisasi unconstrained → <strong>95% A, 5% B</strong> (kejar 0,1%!).</p>\n<p><strong>Realita</strong>: 0,1% = noise. Dengan <strong>max 60%</strong>: 60/40 — robust.</p>\n<p><strong>Pelajaran</strong>: optimisasi = <strong>error maximizer</strong> (Michaud). Constraints + <strong>resampling</strong> = obat. Jangan percaya bobot 2 desimal!</p>'}, 'charts': []}, {'id': 'riskbudget', 'toc': 'Risk Budgeting', 'title': 'Risk Budgeting — Anggaran Risiko', 'body': '<p><strong>Definisi.</strong> <strong>Risk contribution</strong>: RC_i = w_i × ∂σ_p/∂w_i (marginal × bobot). <strong>Risk budgeting</strong>: alokasikan <em>risiko</em> (mis. ekuitas 70%, kredit 20%, rates 10%). <strong>Risk parity</strong>: RC sama semua → bobot ∝ 1/σ (kasus khusus).</p>\n<p><strong>Keunggulan</strong>: stabil (risiko lebih persisten dari return!), diversifikasi sejati.</p>', 'formulas': [{'math': 'RC_i = w_i \\frac{\\partial \\sigma_p}{\\partial w_i} \\quad;\\quad \\sum RC_i = \\sigma_p', 'symbols': ['<Tex math={String.raw`RC_i`} />: kontribusi risiko aset i', 'Risk parity: <Tex math={String.raw`RC_1 = RC_2 = ...`} />', 'Untuk 2 aset tak berkorelasi: <Tex math={String.raw`w_i \\propto 1/\\sigma_i`} />']}], 'intuisi': "Risk budgeting seperti <strong>anggaran belanja</strong>: bukan 'beli apa' (bobot), tapi 'risiko apa' yang dibeli. Risk parity = <strong>semua anak dapat uang jajan sama</strong> (risiko), bukan barang sama (bobot).", 'kapan': 'Alokasi institusi; saat return forecast tidak dipercaya.', 'worked': {'title': '📐 Contoh: RC 60/40 (klik untuk buka)', 'body': '<p>Saham σ 18%, obligasi σ 6%, ρ 0,2, 60/40. σ_p = 11,5%.</p>\n<p><strong>RC saham</strong> ≈ 10,1% (88%), <strong>RC obligasi</strong> ≈ 1,4% (12%).</p>\n<p><strong>Risk parity</strong>: w_saham = (1/18)/(1/18+1/6) = <strong>25%</strong> → RC 50/50. Untuk <em>risiko</em> yang sama, return lebih rendah — <strong>tukar return dengan ketahanan</strong> (atau leverage <em>sehat</em>!).</p>'}, 'charts': [{'data': '[{x: ["Saham", "Obligasi"], y: [88, 12], type: "bar", marker: {color: "#2a7de1"}, name: "60/40"}, {x: ["Saham", "Obligasi"], y: [50, 50], type: "bar", marker: {color: "#16a34a"}, name: "risk parity"}]', 'title': 'Kontribusi risiko: 60/40 vs risk parity (%)', 'layout': '{xaxis: {title: "Aset"}, yaxis: {title: "Kontribusi risiko (%)"}, barmode: "group", showlegend: true}', 'cara': 'Biru = 60/40 nominal; hijau = risk parity. Tinggi = % risiko total.', 'interpretasi': '60/40 <strong>terlihat</strong> seimbang, <strong>risikonya</strong> 88% saham. Risk parity menyamakan 50/50 — <strong>diversifikasi yang sebenarnya</strong>. Pilih: return maksimal (60/40) atau ketahanan maksimal (RP)?'}]}, {'id': 'rebalancing', 'toc': 'Rebalancing & Drift', 'title': 'Rebalancing — Kembali ke Janji', 'body': '<p><strong>Definisi.</strong> <strong>Drift</strong>: bobot menyimpang dari SAA karena return beda. <strong>Calendar</strong>: rebalance periodik (kuartalan/tahunan) — sederhana, bisa <em>terlambat</em>. <strong>Tolerance band</strong>: rebalance jika |w − target| &gt; band (mis. ±5%) — responsif, <em>trading lebih sering</em>.</p>\n<p><strong>Trade-off</strong>: disiplin (tracking IPS) vs <strong>biaya</strong> (komisi, spread, pajak!). <strong>Monitoring</strong>: dashboard drift per kelas aset (job analis!).</p>', 'formulas': [], 'intuisi': 'Rebalancing seperti <strong>spooring mobil</strong>: calendar = spooring tiap 10.000 km (terjadwal); tolerance band = spooring saat setir <em>menarik</em> (responsif). Tidak spooring = ban habis sebelah (risiko tak disadari).', 'kapan': 'Ongoing: monitor drift bulanan; rebalance by band + kalender.', 'worked': {'title': '📐 Contoh: Drift yayasan (klik untuk buka)', 'body': '<p>60/40 → saham +40%, obligasi +5% setahun. Bobot baru: saham = 60×1,4/(60×1,4+40×1,05) = 84/126 = <strong>66,7%</strong>.</p>\n<p><strong>Band ±5%</strong>: 66,7% &gt; 65% → <strong>rebalance</strong> (jual saham, beli obligasi).</p>\n<p><strong>2024</strong>: tanpa rebalance 4 tahun → 78% → koreksi −15% = <strong>Rp2,7M ekstra rugi</strong>. Rebalancing = <strong>asuransi disiplin</strong>.</p>'}, 'charts': []}], 'myths': [{'t': "Optimisasi memberi bobot 'optimal' — ikuti persis.", 'benar': '<strong>Error maximization</strong>: input ±2% → output 95/5 yang absurd. Bobot 2 desimal = <strong>presisi palsu</strong>. Pakai constraints + resampling + <strong>common sense</strong> (round ke 5%). Optimisasi = <em>alat berpikir</em>, bukan mesin jawaban.'}, {'t': 'Rebalancing = market timing yang merugikan (biaya + pajak).', 'benar': '<strong>Tidak rebalance = keputusan pasif</strong> untuk drift (risiko naik diam-diam). Biaya rebalance <em>terukur</em>; biaya drift <em>tersembunyi</em> (Yayasan: Rp2,7M!). <strong>Optimalkan frekuensi</strong> (band + pajak-aware), bukan meniadakan.'}], 'tips': ['<strong>Monitor drift seperti monitor kesehatan.</strong> Dashboard bulanan: bobot aktual vs target per kelas aset + flag breach. Ini <strong>pekerjaan analis portofolio</strong> sehari-hari (job relevance!).', '<strong>Rebalance dengan arus kas.</strong> Kontribusi baru → ke aset <em>underweight</em>; penarikan → dari <em>overweight</em>. Rebalancing <strong>tanpa biaya transaksi</strong>!'], 'labs': [{'heading': 'Kalkulator Risk Contribution', 'intro': 'Hitung kontribusi risiko tiap aset dan bandingkan dengan risk parity.', 'title': 'Lab 1 — Kalkulator Risk Contribution', 'hint': 'Ubah bobot saham 0.6 → 0.25. RC jadi 50/50 — risk parity!', 'code': '# Risk contribution 2 aset\nimport math\nW_S = 0.6   # bobot saham (ubah!)\nSIG_S, SIG_B, RHO = 0.18, 0.06, 0.2\nw_b = 1 - W_S\n\nvar_p = W_S**2*SIG_S**2 + w_b**2*SIG_B**2 + 2*W_S*w_b*RHO*SIG_S*SIG_B\nsig_p = math.sqrt(var_p)\n# marginal contribution\nmrc_s = (W_S*SIG_S**2 + w_b*RHO*SIG_S*SIG_B)/sig_p\nmrc_b = (w_b*SIG_B**2 + W_S*RHO*SIG_S*SIG_B)/sig_p\nrc_s, rc_b = W_S*mrc_s, w_b*mrc_b\n\nprint(f"Vol portofolio: {sig_p:.1%}")\nprint(f"RC saham   : {rc_s/sig_p:.0%} (bobot {W_S:.0%})")\nprint(f"RC obligasi: {rc_b/sig_p:.0%} (bobot {w_b:.0%})")\nprint()\nprint("60/40 nominal -> ~88% risiko dari saham!")\nprint("Risk parity: bobot saham ~25% -> RC 50/50.")\n'}, {'heading': 'Simulator Rebalancing & Drift', 'intro': 'Simulasikan drift 5 tahun dengan & tanpa rebalancing (tolerance band).', 'title': 'Lab 2 — Simulator Rebalancing', 'hint': 'Ubah BAND 0.05 → 0.10 (longgar). Rebalance lebih jarang — hemat biaya, toleransi drift lebih!', 'code': '# Simulator drift & rebalancing (tolerance band)\nimport random\nrandom.seed(44)\nW_TARGET, BAND = 0.60, 0.05  # target & band (ubah BAND!)\nrets_s = [0.40, 0.15, -0.10, 0.25, 0.10]   # return saham 5 thn\nrets_b = [0.05, 0.04, 0.06, 0.03, 0.04]    # obligasi\n\ndef simulasi(pakai_band):\n    w, nilai, n_reb = W_TARGET, 100.0, 0\n    for rs, rb in zip(rets_s, rets_b):\n        w = w*(1+rs)/(w*(1+rs) + (1-w)*(1+rb))\n        nilai *= w*(1+rs) + (1-w)*(1+rb)\n        if pakai_band and abs(w - W_TARGET) > BAND:\n            w, n_reb = W_TARGET, n_reb + 1\n    return nilai, w, n_reb\n\nn1, w1, _ = simulasi(False)\nn2, w2, r2 = simulasi(True)\nprint(f"Tanpa rebalance : nilai {n1:.1f}, bobot saham {w1:.0%} (DRIFT!)")\nprint(f"Dengan band {BAND:.0%}  : nilai {n2:.1f}, bobot {w2:.0%}, {r2}x rebalance")\nprint("\\nDrift = keputusan pasif ambil risiko lebih.")\nprint("Catatan: di bull market ini tanpa-rebalance MENANG nilai,")\nprint("tapi dengan RISIKO 71% saham (langgar IPS!). Rebalancing")\nprint("bukan untuk return maksimal, tapi risiko SESUAI JANJI.")\n'}], 'decisions': [{'kondisi': 'Bobot optimisasi ekstrem (95/5)', 'pakai': 'Tambah constraints / curigai input', 'alasan': 'Error maximization.', 'contoh': 'Max 60% per aset.'}, {'kondisi': 'Return forecast tidak dipercaya', 'pakai': 'Risk parity / risk budgeting', 'alasan': 'Risiko lebih persisten.', 'contoh': 'Alokasi by 1/σ.'}, {'kondisi': 'Drift &gt; band', 'pakai': 'Rebalance', 'alasan': 'Kembali ke IPS.', 'contoh': '66,7% &gt; 65% → jual.'}, {'kondisi': 'Ada arus kas masuk/keluar', 'pakai': 'Rebalance via arus kas', 'alasan': 'Tanpa biaya transaksi.', 'contoh': 'Kontribusi ke underweight.'}], 'rule10': '<ol><li><strong>Constraints</strong> selalu di optimisasi.</li><li><strong>Round</strong> bobot (jangan 2 desimal).</li><li><strong>Monitor drift</strong> bulanan.</li><li><strong>Rebalance by band</strong> + arus kas.</li></ol>', 'case': {'toc': 'Mini-Case: Yayasan 78/22', 'title': 'Portofolio yang Berjalan Sendiri', 'body': '<p>Yayasan: SAA 60/40 (2020), tanpa rebalance → 78/22 (2024) → koreksi −15% → rugi ekstra Rp2,7M.</p>', 'q': "(a) Hitung drift setelah tahun 1 (saham +40%, obligasi +5%). (b) Siapa 'bersalah'? (c) Sistem agar tidak terulang?", 'pembahasan': '<p>(a) <strong>66,7%</strong> saham (breach band ±5% → seharusnya rebalance tahun 1!).</p>\n<p>(b) <strong>Governance</strong>: tidak ada monitoring drift + tidak ada aturan rebalance. Drift = keputusan pasif.</p>\n<p>(c) <strong>Dashboard drift bulanan</strong> (flag breach) + <strong>tolerance band ±5%</strong> tertulis di IPS + <strong>rebalance via arus kas</strong>. Analis portofolio = penjaga disiplin.</p>'}, 'quiz': [{'q': 'Optimisasi memberi 95% saham A (E(R) beda 0,1%). Sikap?', 'options': ['Ikuti persis', 'Curigai error maximization — tambah constraints', 'Tambah lagi', 'Abaikan'], 'correct': 1, 'why': 'Benar: 0,1% = noise. Optimisasi memaksimalkan error input. Constraints + round ke 5%.'}, {'q': '60/40, saham σ18%, obligasi σ6%, ρ0,2. RC saham?', 'options': ['60%', '≈ 88%', '50%', '40%'], 'correct': 1, 'why': "Benar: risiko terkonsentrasi di saham. 'Seimbang' nominal ≠ seimbang risiko."}, {'q': 'Risk parity 2 aset tak berkorelasi. Bobot?', 'options': ['50/50', '∝ 1/σ (samakan RC)', '∝ σ', '100% saham'], 'correct': 1, 'why': 'Benar: bobot berbanding terbalik volatilitas → RC sama. Untuk σ 18/6 → 25/75.'}, {'q': 'Drift ke 66,7%, band ±5% dari 60%. Tindakan?', 'options': ['Biarkan', 'Rebalance ke 60% (breach band)', 'Tunggu 70%', 'Jual semua'], 'correct': 1, 'why': 'Benar: 66,7% &gt; 65% = breach. Rebalancing = kembali ke janji IPS.'}, {'q': 'Cara rebalance tanpa biaya transaksi?', 'options': ['Tidak ada', 'Via arus kas (kontribusi ke underweight)', 'Pinjam dana', 'Tunggu'], 'correct': 1, 'why': 'Benar: arahkan kas masuk/keluar untuk mengoreksi bobot — rebalance gratis.'}], 'rangkum': ['<strong>Optimisasi</strong>: powerful tapi error-maximizing; constraints wajib.', '<strong>Risk budgeting</strong>: alokasikan risiko (RC); risk parity = RC sama.', '<strong>Drift</strong>: bobot berjalan sendiri = keputusan pasif.', '<strong>Rebalancing</strong>: calendar vs tolerance band; via arus kas = gratis.', '<strong>Monitoring</strong>: dashboard drift = kerja analis.', '<strong>Aturan</strong>: jangan percaya bobot 2 desimal; disiplin &gt; presisi.'], 'prev': ['pm-c3-asset-allocation', 'PM-C3'], 'next': ['pm-c5-performance-evaluation', 'PM-C5']}, {'slug': 'pm-c5-performance-evaluation', 'id': 'PM-C5', 'track': 'Portfolio Management', 'title_html': 'Performance Evaluation:<br/>Atribusi & GIPS', 'title_plain': 'Performance Evaluation: Return, Attribution, Benchmark, GIPS', 'chapter_summary': 'CFA L3 evaluasi: TWR vs MWR (IRR/MOIC), atribusi Brinson (allocation/selection/interaction), pemilihan benchmark, dan standar GIPS + praktik pelaporan. Lab kalkulator TWR vs MWR & atribusi Brinson.', 'tujuan': ['Membedakan TWR vs MWR dan kapan masing-masing dipakai.', 'Menghitung atribusi Brinson 3 komponen.', 'Menjelaskan properti benchmark yang baik.', 'Menjelaskan prinsip GIPS dan praktik pelaporan.'], 'story_title': "Cerita: Manajer 'Hebat' yang Menipu Waktu", 'story': '<p><strong>2021</strong>: manajer <em>growth</em> pamer return <strong>+40%</strong>. Investor berbondong-bondong masuk <strong>di puncak</strong>. <strong>2022</strong>: −30%. Investor <em>rata-rata</em> justru <strong>rugi</strong> — masuk besar saat mahal, keluar saat murah.</p>\n<p>Twist-nya: return <strong>dana</strong> (+40% lalu −30%) ≠ return <strong>investor</strong> (rugi!). Dua angka, dua cerita — dan manajer hanya memamerkan yang bagus. <strong>TWR vs MWR</strong> = dua lensa kebenaran. Lesson ini: membaca return tanpa dibohongi.</p>', 'concepts': [{'id': 'twrmwr', 'toc': 'TWR vs MWR', 'title': 'TWR vs MWR — Dua Kebenaran', 'body': '<p><strong>Definisi.</strong> <strong>TWR</strong> (<em>time-weighted</em>): return <em>manajer</em> — hilangkan efek timing arus kas (geometric linking sub-periode). <strong>MWR/IRR</strong> (<em>money-weighted</em>): return <em>investor</em> — bobotkan oleh kapan uang masuk/keluar. <strong>MOIC</strong>: multiple kas (2,0x = uang dobel).</p>\n<p><strong>Aturan</strong>: evaluasi <em>manajer</em> → TWR; evaluasi <em>pengalaman investor</em> → MWR. Beda besar = <strong>timing buruk investor</strong> (behavior gap!).</p>', 'formulas': [{'math': 'TWR = \\prod (1 + r_t) - 1 \\quad;\\quad 0 = \\sum \\frac{CF_t}{(1 + IRR)^t}', 'symbols': ['<Tex math={String.raw`r_t`} />: return sub-periode (antar arus kas)', 'TWR: potong di tiap arus kas, lalu kalikan', 'IRR: tingkat yang membuat NPV arus kas = 0', 'MOIC = total distribusi / total setoran']}], 'intuisi': 'TWR seperti <strong>nilai ujian murni</strong> (kemampuan siswa); MWR seperti <strong>nilai rapor dengan kehadiran</strong> (pengalaman nyata: bolos saat materi mudah, hadir saat susah = nilai jeblok). Keduanya benar — <em>jawab pertanyaan berbeda</em>.', 'kapan': 'Fund factsheet → TWR; laporan ke investor individu → MWR juga.', 'worked': {'title': '📐 Contoh: Cerita manajer growth (klik untuk buka)', 'body': "<p>Dana: 2021 +40%, 2022 −30%. <strong>TWR</strong> = 1,4 × 0,7 − 1 = <strong>−2%</strong>.</p>\n<p>Investor: setor 100 (→140), tambah 400 = 540, lalu ×0,7 = <strong>378</strong>. <strong>IRR</strong> ≈ <strong>−21%</strong>! <strong>MOIC</strong> = 378/500 = <strong>0,76x</strong>.</p>\n<p>Manajer: '−2% (pasar sulit)'. Investor: '−20%!'. <strong>Selisih 18 poin = behavior gap</strong> — investor membeli di puncak. Evaluasi jujur = tampilkan <em>keduanya</em>.</p>"}, 'charts': []}, {'id': 'brinson', 'toc': 'Atribusi Brinson', 'title': 'Atribusi Brinson — Bedah Nilai Tambah', 'body': "<p><strong>Definisi.</strong> <strong>Excess return</strong> = <strong>allocation</strong> (bobot beda × return benchmark sektor) + <strong>selection</strong> (bobot benchmark × return beda) + <strong>interaction</strong> (bobot beda × return beda).</p>\n<p><strong>Gunanya</strong>: jawab 'manajer hebat <em>di apa</em>?' — pilih sektor (allocation) atau pilih saham (selection)?</p>", 'formulas': [{'math': 'R_p - R_b = \\sum (w_p - w_b)R_b + \\sum w_b(R_p - R_b) + \\sum (w_p - w_b)(R_p - R_b)', 'symbols': ['Allocation: <Tex math={String.raw`(w_p - w_b) R_b`} /> — bobot menyimpang × return sektor', 'Selection: <Tex math={String.raw`w_b (R_p - R_b)`} /> — saham mengalahkan sektornya?', 'Interaction: <Tex math={String.raw`(w_p - w_b)(R_p - R_b)`} /> — keduanya sekaligus']}], 'intuisi': "Atribusi seperti <strong>bedah nilai rapor</strong>: allocation = 'pilih jurusan yang tepat' (sektor); selection = 'ranking di jurusan' (saham); interaction = 'keduanya'. Tanpa bedah, 'nilai bagus' tidak bisa direplikasi.", 'kapan': 'Review manajer kuartalan; keputusan retain/fire.', 'worked': {'title': '📐 Contoh: Bedah manajer (klik untuk buka)', 'body': '<p>Sektor teknologi: w_p 30% vs w_b 20%; R_p 25% vs R_b 15%.</p>\n<p><strong>Allocation</strong> = (30%−20%)×15% = <strong>+1,5%</strong> (overweight sektor bagus ✓).</p>\n<p><strong>Selection</strong> = 20%×(25%−15%) = <strong>+2,0%</strong> (sahamnya mengalahkan ✓).</p>\n<p><strong>Interaction</strong> = 10%×10% = <strong>+1,0%</strong>.</p>\n<p><strong>Total +4,5%</strong>: manajer hebat di <em>keduanya</em> — layak dipertahankan (dan layak fee!).</p>'}, 'charts': [{'data': '[{x: ["Allocation", "Selection", "Interaction"], y: [1.5, 2.0, 1.0], type: "bar", marker: {color: ["#2a7de1","#16a34a","#e8a838"]}, text: ["+1,5%","+2,0%","+1,0%"], textposition: "outside"}]', 'title': 'Atribusi Brinson: sumber excess return +4,5%', 'layout': '{xaxis: {title: "Komponen"}, yaxis: {title: "Kontribusi (%)"}, showlegend: false}', 'cara': 'Tinggi batang = kontribusi tiap komponen ke excess return.', 'interpretasi': 'Manajer unggul <strong>di kedua</strong> dimensi: pilih sektor tepat (+1,5%) <em>dan</em> pilih saham tepat (+2,0%). Jika hanya allocation positif tapi selection negatif = <strong>tukang tebak sektor</strong>, bukan stock picker — fee aktif tidak layak.'}]}, {'id': 'gips', 'toc': 'Benchmark & GIPS', 'title': 'Benchmark & GIPS — Standar Kejujuran', 'body': '<p><strong>Definisi.</strong> <strong>Benchmark baik</strong>: <em>specified in advance</em>, <em>measurable</em>, <em>unambiguous</em>, <em>reflective of views</em>, <em>owned</em>, <em>investable</em>. <strong>GIPS</strong>: standar global presentasi kinerja — <em>composite</em> (semua portofolio discretionary!), <em>gross &amp; net</em>, <em>fee disclosure</em>, <strong>verifikasi independen</strong>.</p>\n<p><strong>Dosa klasik</strong>: <em>survivorship bias</em> (tampilkan hanya dana hidup), <em>cherry-picking</em> periode, benchmark yang <strong>diganti</strong> saat kalah.</p>', 'formulas': [], 'intuisi': "GIPS seperti <strong>label nutrisi makanan</strong>: sebelum ada, produsen klaim 'sehat!' seenaknya. GIPS memaksa <strong>semua produk</strong> (termasuk yang gagal!) + <strong>cara ukur standar</strong> + <strong>auditor</strong>. Klaim 'return 20%' tanpa GIPS = iklan, bukan fakta.", 'kapan': 'Factsheet, marketing manajer, due diligence — tuntut GIPS-compliant.', 'worked': {'title': '📐 Contoh: Audit factsheet (klik untuk buka)', 'body': "<p>Factsheet: 'Return 5 tahun 15%/thn!' Cek GIPS:</p>\n<p><strong>(1)</strong> Composite? Hanya 'strategi unggulan' (2 dari 10 dana) → <strong>survivorship!</strong> <strong>(2)</strong> Gross/net? Gross (fee 2%!) → net = <strong>13%</strong>. <strong>(3)</strong> Benchmark? Diganti 2x.</p>\n<p><strong>Verdict</strong>: klaim 15% → realita ~10% vs benchmark. <strong>Tolak.</strong> GIPS = kacamata X-ray factsheet.</p>"}, 'charts': []}], 'myths': [{'t': 'Return dana = return yang saya terima. Manajer +40%/-30% artinya saya -2%.', 'benar': 'Investor cerita ini: <strong>IRR −20%, MOIC 0,7x</strong> (FOMO di puncak!). TWR = skill manajer; MWR = pengalamanmu. <strong>Behavior gap</strong> rata-rata investor = 2–4%/tahun (Dalbar). Ukur keduanya — dan <strong>jangan FOMO</strong>.'}, {'t': 'Factsheet 15%/tahun = bukti manajer hebat.', 'benar': 'Tanpa GIPS: mungkin <strong>survivorship</strong> (8 dana gagal disembunyikan!), <strong>gross</strong> (net 13%), <strong>benchmark diganti</strong>. Tuntut: composite lengkap, gross &amp; net, benchmark konsisten, verifikasi. <strong>Iklan ≠ bukti.</strong>'}], 'tips': ['<strong>Selalu minta dua angka: TWR dan MWR.</strong> Jika manajer hanya memberi TWR — tanyakan pengalaman investor rata-rata. Selisih besar = red flag perilaku (atau marketing).', '<strong>Bangun template pelaporan standar.</strong> TWR/MWR, atribusi Brinson, benchmark konsisten, gross vs net — tiap kuartal, format sama. Konsistensi format = <strong>kejujuran yang bisa diaudit</strong> (job relevance: Power BI reporting!).'], 'labs': [{'heading': 'Kalkulator TWR vs MWR', 'intro': 'Hitung return manajer (TWR) vs pengalaman investor (MWR/IRR).', 'title': 'Lab 1 — Kalkulator TWR vs MWR', 'hint': 'Ubah TAMBAH 400 → 100 (tidak FOMO). IRR mendekati TWR — timing menentukan!', 'code': '# TWR vs MWR (IRR sederhana: 2 periode)\nR1, R2 = 0.40, -0.30      # return dana per tahun\nSETOR1 = 100              # awal tahun 1\nTAMBAH = 400              # awal tahun 2 (ubah!)\n\ntwr = (1+R1)*(1+R2) - 1\nnilai = (SETOR1*(1+R1) + TAMBAH)*(1+R2)\ntotal_setor = SETOR1 + TAMBAH\n# IRR: -S1 - T/(1+r) + N/(1+r)^2 = 0 -> selesaikan kuadrat\nimport math\na, b, c = nilai, -(SETOR1 + TAMBAH) - SETOR1, 0  # bentuk: a x^2 + b x, x=1/(1+r)\n# -S1 - T*x + N*x^2 = 0\nA, B, C = nilai, -TAMBAH, -SETOR1\nD = B*B - 4*A*C\nx = (-B + math.sqrt(D))/(2*A)\nirr = 1/x - 1\n\nprint(f"TWR (manajer) : {twr:.1%}")\nprint(f"IRR (investor): {irr:.1%}")\nprint(f"MOIC          : {nilai/total_setor:.2f}x")\nprint(f"Behavior gap  : {twr-irr:+.1%}")\nprint("\\nFOMO di puncak = IRR jauh di bawah TWR.")\n'}, {'heading': 'Kalkulator Atribusi Brinson', 'intro': 'Bedah excess return jadi allocation + selection + interaction.', 'title': 'Lab 2 — Kalkulator Brinson', 'hint': 'Ubah RP 0.25 → 0.10 (saham kalah dari sektor). Selection negatif — manajer bukan stock picker!', 'code': '# Atribusi Brinson 1 sektor\nW_P, W_B = 0.30, 0.20   # bobot portofolio vs benchmark\nR_P, R_B = 0.25, 0.15   # return portofolio vs benchmark sektor (ubah R_P!)\n\nalloc = (W_P - W_B) * R_B\nselec = W_B * (R_P - R_B)\ninter = (W_P - W_B) * (R_P - R_B)\ntotal = alloc + selec + inter\n\nprint(f"Allocation : {alloc:+.2%}")\nprint(f"Selection  : {selec:+.2%}")\nprint(f"Interaction: {inter:+.2%}")\nprint(f"Total      : {total:+.2%}  (cek: {(W_P*R_P - W_B*R_B):+.2%})")\nprint()\nprint("Selection negatif + allocation positif = tukang tebak sektor.")\n'}], 'decisions': [{'kondisi': 'Evaluasi skill manajer', 'pakai': 'TWR vs benchmark', 'alasan': 'Bersih dari timing investor.', 'contoh': 'Factsheet GIPS.'}, {'kondisi': 'Laporan ke investor', 'pakai': 'MWR/IRR + MOIC juga', 'alasan': 'Pengalaman nyata.', 'contoh': 'Private banking.'}, {'kondisi': 'Putuskan retain/fire manajer', 'pakai': 'Atribusi Brinson multi-periode', 'alasan': 'Skill apa? Konsisten?', 'contoh': 'Selection + 3 tahun.'}, {'kondisi': 'Terima marketing manajer', 'pakai': 'Cek GIPS: composite, gross/net, benchmark', 'alasan': 'Saring iklan.', 'contoh': 'Audit factsheet.'}], 'rule10': '<ol><li><strong>TWR</strong> = manajer; <strong>MWR</strong> = investor.</li><li><strong>Bedah</strong> dengan Brinson.</li><li><strong>Benchmark</strong>: konsisten &amp; investable.</li><li><strong>Tuntut GIPS</strong>.</li></ol>', 'case': {'toc': 'Mini-Case: Manajer Growth', 'title': 'Halo +40%, Selamat Tinggal −30%', 'body': '<p>Dana: +40% (2021), −30% (2022). Investor setor 100 lalu FOMO 400 di puncak.</p>', 'q': '(a) TWR, IRR, MOIC? (b) Siapa salah? (c) Sistem pencegah?', 'pembahasan': "<p>(a) <strong>TWR −2%</strong>; <strong>IRR ≈ −20%</strong>; <strong>MOIC 0,7x</strong>.</p>\n<p>(b) <strong>Behavior gap investor</strong> (FOMO di puncak) — tapi manajer ikut 'bersalah' jika marketing hanya pamer +40% tanpa konteks risiko.</p>\n<p>(c) <strong>IPS + rebalancing</strong> (cuan 2021 → rebalance, bukan tambah!); <strong>edukasi MWR</strong>; <strong>aturan kontribusi otomatis</strong> (DCA) bukan FOMO.</p>"}, 'quiz': [{'q': 'Dana +40% lalu −30%. TWR?', 'options': ['+10%', '−2%', '+5%', '−30%'], 'correct': 1, 'why': "Benar: 1,4×0,7−1 = −2%. Volatilitas = 'pajak' return (volatility drag!)."}, {'q': 'Investor setor 100, tambah 400 di puncak. IRR ≈ ?', 'options': ['−2%', '−20%', '+10%', '0%'], 'correct': 1, 'why': 'Benar: ≈ −20%, MOIC 0,7x. Timing buruk = behavior gap 18 poin!'}, {'q': 'Allocation positif, selection negatif konsisten. Artinya?', 'options': ['Stock picker hebat', 'Tukang tebak sektor — fee aktif tidak layak', 'Manajer pasif', 'Beruntung'], 'correct': 1, 'why': 'Benar: skill-nya di bobot sektor, bukan pilih saham. Bayar murah atau ganti.'}, {'q': "Factsheet '15%' tapi hanya 2 dari 10 dana ditampilkan. Ini?", 'options': ['GIPS compliant', 'Survivorship bias', 'Net return', 'Benchmark baik'], 'correct': 1, 'why': 'Benar: dana gagal disembunyikan. Tuntut composite SEMUA portofolio discretionary.'}, {'q': 'Untuk evaluasi skill manajer murni, pakai?', 'options': ['MWR', 'TWR vs benchmark konsisten', 'MOIC', 'Return 1 bulan'], 'correct': 1, 'why': 'Benar: TWR menghilangkan efek timing arus kas investor. MWR untuk pengalaman investor.'}], 'rangkum': ['<strong>TWR</strong> (manajer) vs <strong>MWR/IRR</strong> (investor) vs <strong>MOIC</strong>.', '<strong>Behavior gap</strong>: timing investor bisa −2–4%/tahun.', '<strong>Brinson</strong>: allocation + selection + interaction.', '<strong>Benchmark</strong>: ditetapkan di muka, investable, konsisten.', '<strong>GIPS</strong>: composite penuh, gross &amp; net, verifikasi.', '<strong>Aturan</strong>: iklan ≠ bukti; tampilkan dua angka.'], 'prev': ['pm-c4-portfolio-construction', 'PM-C4'], 'next': ['pm-c6-behavioral', 'PM-C6']}, {'slug': 'pm-c6-behavioral', 'id': 'PM-C6', 'track': 'Portfolio Management', 'title_html': 'Behavioral Finance:<br/>Musuh di Cermin', 'title_plain': 'Behavioral Finance: Bias Kognitif & Emosional', 'chapter_summary': 'CFA L3 behavioral: bias kognitif vs emosional (anchoring, confirmation, loss aversion, overconfidence, herding...), prospect theory, dan mitigasi via proses & IPS. Lab simulator prospect theory & pengklasifikasi bias.', 'tujuan': ['Membedakan bias kognitif vs emosional dan contohnya.', 'Menjelaskan prospect theory dan loss aversion.', 'Mengidentifikasi bias dalam keputusan nyata.', 'Merancang mitigasi: proses, checklist, IPS.'], 'story_title': "Cerita: Rp100 Juta yang 'Tidak Terasa'", 'story': "<p><strong>Bu Rina</strong> rugi <strong>Rp100jt</strong> di saham gorengan — <em>tetap pegang</em> ('nanti balik'). Di sisi lain, saham bagus untung <strong>Rp20jt</strong> — <em>langsung jual</em> ('amankan!'). Setahun kemudian: gorengan <strong>−80%</strong>, yang bagus <strong>+200%</strong>.</p>\n<p>Twist-nya: <strong>keduanya keputusan emosional yang sama</strong> — <strong>disposition effect</strong>: jual pemenang terlalu cepat (takut rugi balik), pegang pecundang terlalu lama (takut akui salah). <strong>Otaknya bekerja persis terbalik</strong> dari yang menguntungkan. Lesson ini: mengenali musuh di cermin.</p>", 'concepts': [{'id': 'kognitif', 'toc': 'Bias Kognitif', 'title': 'Bias Kognitif — Bug Perangkat Lunak', 'body': "<p><strong>Definisi.</strong> <strong>Bias kognitif</strong> = error <em>penalaran</em> (bisa diperbaiki dengan informasi/proses): <em>anchoring</em> (terpaku angka pertama — 'dulu Rp10rb!'), <em>confirmation</em> (cari info yang setuju), <em>hindsight</em> ('sudah kuduga!'), <em>framing</em> (90% selamat vs 10% mati), <em>availability</em> (krisis terakhir = 'pasti terulang'), <em>representativeness</em> (saham bagus = perusahaan bagus).</p>\n<p><strong>Obat</strong>: data, checklist, <em>devil's advocate</em>.</p>", 'formulas': [], 'intuisi': 'Bias kognitif seperti <strong>bug software</strong>: bisa di-patch (data, proses). Anchoring = <strong>harga coret</strong> di mal (Rp1jt → Rp500rb terasa murah, padahal HPP Rp200rb!). Sadar = kebal separuh.', 'kapan': 'Analisis investasi: paksa cari <em>3 alasan tesis ini salah</em>.', 'worked': {'title': '📐 Contoh: Anchoring IHSG (klik untuk buka)', 'body': "<p>IHSG 7.300 → turun ke 6.800. Investor: <em>'murah! dulu 7.300'</em> — <strong>anchor</strong> ke puncak.</p>\n<p><strong>Cek valuasi</strong>: P/E 18 (masih di atas rata-rata 15!) → <strong>tidak murah</strong>, hanya 'lebih murah dari puncak'.</p>\n<p><strong>Obat</strong>: ganti anchor → <strong>valuasi historis</strong> (P/E 10-tahunan), bukan harga terakhir. Harga = opini; valuasi = fakta.</p>"}, 'charts': []}, {'id': 'emosional', 'toc': 'Bias Emosional', 'title': 'Bias Emosional — Bug Perangkat Keras', 'body': "<p><strong>Definisi.</strong> <strong>Bias emosional</strong> = dari <em>perasaan</em> (sulit 'diedukasi', harus <em>dikelola</em>): <em>loss aversion</em> (rugi 2x lebih sakit dari untung), <em>overconfidence</em> (90% supir merasa di atas rata-rata!), <em>regret aversion</em> (takut salah → tidak bertindak), <em>herding</em> (ikut kerumunan aman), <em>status quo</em>, <em>endowment</em> (barang sendiri terasa lebih mahal).</p>\n<p><strong>Prospect theory</strong>: nilai = fungsi <strong>perubahan</strong> (bukan level), <strong>cembung untuk untung, cekung untuk rugi</strong> → risk-averse saat untung, <strong>risk-seeking saat rugi</strong> (pegang gorengan!).</p>", 'formulas': [{'math': 'v(x) = x^{\\alpha}, \\quad x \\geq 0', 'symbols': ['Untung: cekung (diminishing sensitivity) → cepat puas → jual']}, {'math': 'v(x) = -\\lambda(-x)^{\\beta}, \\quad x < 0', 'symbols': ['Rugi: cembung → risk-seeking → pegang/tambah', '<Tex math={String.raw`\\lambda \\approx 2{,}25`} />: rugi 2,25x lebih sakit (loss aversion)', '<Tex math={String.raw`\\alpha, \\beta \\approx 0{,}88`} />: diminishing sensitivity']}], 'intuisi': "Loss aversion seperti <strong>lidah yang 2x lebih peka pahit</strong>: sesendok gula (untung Rp1jt) vs sesendok empedu (rugi Rp1jt) — pahitnya <em>jauh</em> lebih terasa. Evolusi: menghindari racun &gt; mengejar madu. Di pasar, 'racun' = volatilitas normal.", 'kapan': "Keputusan jual/tahan: tanya 'beli baru di harga ini?' — jika tidak, jual.", 'worked': {'title': '📐 Contoh: Bu Rina di-cermin (klik untuk buka)', 'body': "<p><strong>Pemenang +Rp20jt</strong> (cekung → cepat puas → <strong>jual</strong> ✓ emosional, ✗ finansial).</p>\n<p><strong>Pecundang −Rp100jt</strong> (cembung → risk-seeking → <strong>pegang/tambah</strong> ✗✗).</p>\n<p><strong>Tes cermin</strong>: 'Jika kas hari ini, beli gorengan ini di harga sekarang?' → <strong>Tidak</strong> → jual. <strong>Endowment effect</strong> membuatnya terasa 'milikku, spesial' — padahal pasar tidak peduli.</p>"}, 'charts': [{'data': '[{x: [-100,-80,-60,-40,-20,0,20,40,60,80,100], y: [-2.8,-2.3,-1.8,-1.3,-0.8,0,0.6,0.8,0.9,1.0,1.05], type: "scatter", mode: "lines", marker: {color: "#2a7de1"}, line: {width: 3}}]', 'title': 'Fungsi nilai prospect theory (λ = 2,25)', 'layout': '{xaxis: {title: "Perubahan (Rp jt)"}, yaxis: {title: "Nilai psikologis"}, showlegend: false}', 'cara': "Sumbu-x = untung/rugi; sumbu-y = 'rasanya'. Kiri bawah vs kanan atas.", 'interpretasi': 'Kurva <strong>lebih curam di kiri</strong> (rugi Rp50jt terasa −1,6 vs untung +Rp50jt hanya +0,85). <strong>Cembung saat rugi</strong> = nekat tambah risiko (pegang gorengan); <strong>cekung saat untung</strong> = cepat puas (jual pemenang). Inilah <strong>mesin disposition effect</strong> — kenali bentuknya di dirimu.'}]}, {'id': 'mitigasi', 'toc': 'Mitigasi', 'title': 'Mitigasi — Sistem Melawan Diri Sendiri', 'body': "<p><strong>Definisi.</strong> <strong>Kognitif</strong> → perbaiki (data, checklist, devil's advocate). <strong>Emosional</strong> → <em>kelola</em> (tidak bisa diedukasi!): <strong>IPS</strong> (aturan tertulis saat tenang), <strong>automasi</strong> (DCA, rebalance), <strong>cooling-off</strong> (tunda 72 jam), <strong>pre-commitment</strong> (stop-loss otomatis).</p>\n<p><strong>Prinsip</strong>: jangan andalkan <em>willpower</em> — bangun <strong>sistem</strong> yang benar bahkan saat emosi salah.</p>", 'formulas': [], 'intuisi': "Mitigasi seperti <strong>Odysseus &amp; siren</strong>: tahu akan tergoda (emosi) → <strong>ikat diri ke tiang</strong> (IPS, automasi) <em>sebelum</em> mendengar nyanyian. Mengandalkan 'tekad' saat siren bernyanyi = kapal karam.", 'kapan': 'Desain proses investasi: aturan ditulis saat tenang, dijalankan saat panik.', 'worked': {'title': '📐 Contoh: Sistem anti-Bu Rina (klik untuk buka)', 'body': "<p><strong>Aturan tertulis</strong> (saat tenang): (1) <strong>Stop-loss −15%</strong> otomatis (lawan disposition); (2) <strong>Ambil untung bertahap</strong> +25/+50% (lawan cepat puas); (3) <strong>Tes cermin</strong> tiap posisi merah; (4) <strong>Cooling-off 72 jam</strong> sebelum beli 'panas'.</p>\n<p><strong>Hasil</strong>: gorengan terjual di −15% (rugi Rp15jt, bukan Rp80jt); pemenang dipegang bertahap (+120%). <strong>Sistem &gt; emosi.</strong></p>"}, 'charts': []}], 'myths': [{'t': 'Saya rasional — behavioral finance untuk orang lain.', 'benar': '<strong>90% supir merasa di atas rata-rata</strong> — termasuk kamu. Overconfidence = bias yang <em>menyembunyikan</em> bias lain. Tes: catat <em>semua</em> prediksi + hasilnya 1 tahun. <strong>Jurnal = cermin</strong> yang tidak bisa dibohongi.'}, {'t': 'Bias emosional bisa dihilangkan dengan belajar.', 'benar': '<strong>Tidak.</strong> Kognitif bisa di-patch (data); emosional hanya bisa <strong>dikelola</strong> (sistem). Ahli behavioral pun FOMO — bedanya mereka punya <strong>IPS + automasi</strong>. Jangan lawan ombak; <strong>bangun kapal</strong>.'}], 'tips': ["<strong>Tulis jurnal keputusan.</strong> Tiap beli/jual: tesis + harga + tanggal + 'apa yang membuatku salah?'. Review tahunan = <strong>obat overconfidence & hindsight</strong> paling murah.", "<strong>Pasang 'tiang Odysseus' sebelum badai.</strong> Stop-loss otomatis, DCA otomatis, cooling-off 72 jam — <em>sekarang</em>, saat tenang. Aturan yang dibuat saat panik = tidak ada aturan."], 'labs': [{'heading': 'Simulator Prospect Theory', 'intro': 'Rasakan fungsi nilai: pilih antara pasti vs gamble di wilayah untung & rugi.', 'title': 'Lab 1 — Simulator Prospect Theory', 'hint': 'Ubah LAMBDA 2.25 → 1.0 (tanpa loss aversion). Pilihan berubah — rasakan bedanya!', 'code': '# Prospect theory: v(x) untung vs rugi (EV sama, pilihan beda!)\nLAMBDA = 2.25   # loss aversion (ubah ke 1.0!)\nALPHA = 0.88\n\ndef v(x):\n    return x**ALPHA if x >= 0 else -LAMBDA*(-x)**ALPHA\n\n# Skenario UNTUNG: pasti +90 vs 90% dapat +100 (EV sama = 90)\npasti_u, gamble_u = v(90), 0.9*v(100)\n# Skenario RUGI: pasti -90 vs 90% rugi -100 (EV sama = -90)\npasti_r, gamble_r = v(-90), 0.9*v(-100)\n\nprint(f"UNTUNG: pasti {pasti_u:.1f} vs gamble {gamble_u:.1f} -> pilih {\'PASTI\' if pasti_u>gamble_u else \'GAMBLE\'} (risk-averse: amankan)")\nprint(f"RUGI  : pasti {pasti_r:.1f} vs gamble {gamble_r:.1f} -> pilih {\'PASTI\' if pasti_r>gamble_r else \'GAMBLE\'} (risk-seeking: nekat)")\nprint()\nprint("EV SAMA, pilihan BEDA: untung -> amankan; rugi -> nekat.")\nprint("Itulah disposition effect. Ubah LAMBDA=1.0: asimetri hilang.")\n'}, {'heading': 'Pengklasifikasi Bias', 'intro': 'Klasifikasikan skenario ke bias yang tepat — latihan deteksi.', 'title': 'Lab 2 — Detektor Bias', 'hint': 'Ubah SKENARIO 1 → 4. Tiap nomor = bias berbeda. Tebak dulu sebelum lihat jawaban!', 'code': '# Detektor bias: tebak dulu, lalu cek\nSKENARIO = 1  # 1..4 (ubah!)\n\nbank = {\n 1: ("\'Saham ini dulu Rp10rb, sekarang Rp6rb = murah!\'",\n     "ANCHORING (kognitif) - terpaku harga masa lalu, bukan valuasi."),\n 2: ("\'Semua analis bilang beli, ikut saja.\'",\n     "HERDING (emosional) - aman di kerumunan, salah bersama."),\n 3: ("\'Rugi Rp100jt, tahan... nanti balik. Jual yang untung Rp20jt.\'",\n     "DISPOSITION EFFECT (prospect theory) - cembung saat rugi, cekung saat untung."),\n 4: ("\'Saya sudah baca 10 laporan yang SETUJU dengan saya.\'",\n     "CONFIRMATION BIAS (kognitif) - cari yang mengiyakan, bukan menguji."),\n}\nteks, jawab = bank[SKENARIO]\nprint("Skenario:", teks)\nprint()\ninput("Tebak biasnya... (Enter untuk jawaban)")\nprint("Jawaban:", jawab)\n'}], 'decisions': [{'kondisi': 'Analisis investasi', 'pakai': 'Paksa 3 alasan tesis salah', 'alasan': 'Lawan confirmation.', 'contoh': "Devil's advocate."}, {'kondisi': 'Posisi merah dalam', 'pakai': 'Tes cermin: beli baru di harga ini?', 'alasan': 'Lawan endowment + disposition.', 'contoh': 'Tidak → jual.'}, {'kondisi': "Ingin beli 'panas' (FOMO)", 'pakai': 'Cooling-off 72 jam', 'alasan': 'Emosi memudar, data tinggal.', 'contoh': 'Aturan tertulis.'}, {'kondisi': 'Desain proses', 'pakai': 'Automasi + IPS (tiang Odysseus)', 'alasan': 'Sistem &gt; willpower.', 'contoh': 'DCA + stop otomatis.'}], 'rule10': '<ol><li><strong>Kognitif</strong> = patch; <strong>emosional</strong> = kelola.</li><li><strong>Jurnal</strong> semua keputusan.</li><li><strong>Tes cermin</strong> untuk posisi merah.</li><li><strong>Sistem</strong> &gt; tekad.</li></ol>', 'case': {'toc': 'Mini-Case: Bu Rina', 'title': 'Rp100 Jt yang Tidak Terasa', 'body': "<p>Bu Rina: pegang gorengan −Rp100jt ('nanti balik'), jual pemenang +Rp20jt ('amankan'). Setahun: −80% vs +200%.</p>", 'q': '(a) Nama biasnya? (b) Mekanisme prospect theory? (c) Sistem pencegah?', 'pembahasan': '<p>(a) <strong>Disposition effect</strong> (+ endowment effect di pecundang).</p>\n<p>(b) <strong>Cembung saat rugi</strong> → risk-seeking (pegang/tambah); <strong>cekung saat untung</strong> → risk-averse (jual cepat). λ=2,25 memperkuat.</p>\n<p>(c) <strong>Stop-loss −15% otomatis</strong> + <strong>tes cermin</strong> + <strong>ambil untung bertahap</strong> + <strong>jurnal</strong>. Ditulis saat tenang, dieksekusi saat emosi.</p>'}, 'quiz': [{'q': "'Dulu Rp10rb, sekarang Rp6rb = murah!' Bias?", 'options': ['Herding', 'Anchoring (kognitif)', 'Loss aversion', 'Overconfidence'], 'correct': 1, 'why': 'Benar: terpaku angka masa lalu. Obat: ganti anchor ke valuasi historis (P/E), bukan harga.'}, {'q': 'λ = 2,25 artinya?', 'options': ['Untung 2,25x lebih nikmat', 'Rugi 2,25x lebih sakit dari untung setara', 'Risiko 2,25x', 'Tidak ada arti'], 'correct': 1, 'why': 'Benar: loss aversion. Rugi Rp1jt ≈ sakitnya untung Rp2,25jt.'}, {'q': 'Saat rugi, orang cenderung?', 'options': ['Risk-averse', 'Risk-seeking (pegang/tambah pecundang)', 'Netral', 'Jual semua'], 'correct': 1, 'why': 'Benar: fungsi nilai cembung di wilayah rugi → nekat. Inilah mesin disposition effect.'}, {'q': 'Bias emosional paling tepat diatasi dengan?', 'options': ['Belajar lebih giat', 'Sistem: IPS + automasi + pre-commitment', 'Willpower', 'Abaikan'], 'correct': 1, 'why': "Benar: emosional tidak bisa 'diedukasi hilang' — hanya dikelola via sistem (tiang Odysseus)."}, {'q': "'Semua analis bilang beli, ikut saja.' Bias?", 'options': ['Confirmation', 'Herding (emosional)', 'Framing', 'Hindsight'], 'correct': 1, 'why': 'Benar: ikut kerumunan terasa aman. Obat: tesis independen tertulis SEBELUM lihat konsensus.'}], 'rangkum': ['<strong>Kognitif</strong> (anchoring, confirmation, hindsight, framing, availability): patch dengan data &amp; proses.', '<strong>Emosional</strong> (loss aversion, overconfidence, herding, regret): kelola dengan sistem.', '<strong>Prospect theory</strong>: λ≈2,25; cembung-rugi, cekung-untung → disposition effect.', "<strong>Tes cermin</strong>: 'beli baru di harga ini?'", '<strong>Mitigasi</strong>: IPS, automasi, cooling-off, jurnal, pre-commitment.', '<strong>Aturan</strong>: sistem &gt; tekad; jurnal = cermin.'], 'prev': ['pm-c5-performance-evaluation', 'PM-C5'], 'next': ['pm-c7-fixed-income-portfolio', 'PM-C7']}, {'slug': 'pm-c7-fixed-income-portfolio', 'id': 'PM-C7', 'track': 'Portfolio Management', 'title_html': 'Fixed Income Portfolio:<br/>Imunisasi & Strategi Aktif', 'title_plain': 'Fixed Income Portfolio: Immunization, Laddering, Active', 'chapter_summary': 'CFA L3 obligasi: imunisasi (duration/cash-flow/horizon matching), laddering vs barbell/bullet, dan strategi aktif (rate anticipation, spread, credit). Lab pemeriksa imunisasi & pembangun ladder.', 'tujuan': ['Menjelaskan 3 teknik imunisasi dan syaratnya.', 'Membedakan ladder, barbell, bullet.', 'Menjelaskan strategi aktif obligasi.', 'Menghitung risiko reinvestment vs price.'], 'story_title': 'Cerita: Janji Rp1 Miliar 10 Tahun Lagi', 'story': "<p><strong>Yayasan beasiswa</strong> harus membayar <strong>Rp1 miliar</strong> dalam <strong>10 tahun</strong>. Bendahara membeli obligasi <strong>10 tahun</strong> — 'kan jatuh temponya pas?' <strong>2022</strong>: rate naik 3% → harga obligasi <strong>anjlok 25%</strong>. Panik? Tidak perlu — jika <em>dipegang sampai jatuh tempo</em>, Rp1M tetap terbayar (kupon reinvestasi bahkan <em>lebih tinggi</em>!).</p>\n<p>Twist-nya: <strong>risiko harga</strong> (rate naik → harga turun) dan <strong>risiko reinvestasi</strong> (rate turun → kupon reinvest rendah) <strong>saling meniadakan</strong> <em>tepat di duration</em>! Inilah <strong>imunisasi</strong> — keajaiban matematika obligasi. Lesson ini: janji yang terkunci.</p>", 'concepts': [{'id': 'imunisasi', 'toc': 'Imunisasi', 'title': 'Imunisasi — Kunci Matematika', 'body': '<p><strong>Definisi.</strong> <strong>Imunisasi</strong>: strukturkan aset agar <strong>kewajiban terpenuhi apapun pergerakan rate</strong> (paralel). <strong>3 teknik</strong>: (1) <strong>Cash-flow matching</strong> (dedikasi): arus kas aset = kewajiban — <em>paling aman, paling mahal</em>; (2) <strong>Duration matching</strong>: Macaulay duration aset = horizon kewajiban; (3) <strong>Horizon matching</strong>: kombinasi (dekat: cash-flow, jauh: duration).</p>\n<p><strong>Syarat</strong>: <em>rebalancing</em> berkala (duration meleset seiring waktu!); hanya lindungi <strong>parallel shift</strong>.</p>', 'formulas': [{'math': 'D_{Mac} = \\frac{\\sum t \\cdot PV(CF_t)}{P} \\quad;\\quad \\text{Imunisasi: } D_{aset} = H_{kewajiban}', 'symbols': ['<Tex math={String.raw`D_{Mac}`} />: Macaulay duration (rata-rata tertimbang waktu arus kas)', 'Price risk vs reinvestment risk <strong>saling hapus</strong> tepat di <Tex math={String.raw`D_{Mac}`} />', 'Setelah rate berubah: <strong>rebalance</strong> (duration bergeser!)', 'Critical: hanya untuk <strong>parallel shift</strong>; twist butuh key-rate duration']}], 'intuisi': 'Imunisasi seperti <strong>jungkat-jungkit seimbang</strong>: price risk (kiri) vs reinvestment risk (kanan). Tepat di titik tumpu (duration) = <strong>seimbang apapun guncangan</strong> (rate). Tapi jungkat-jungkit <em>bergeser</em> seiring waktu → <strong>sesuaikan tumpu</strong> (rebalance!).', 'kapan': 'Kewajiban tunggal/majemuk yang pasti: pensiun, yayasan, asuransi.', 'worked': {'title': '📐 Contoh: Beasiswa Rp1M (klik untuk buka)', 'body': "<p>Kewajiban Rp1M dalam 10 tahun. Beli obligasi 10 tahun <strong>par, kupon = yield</strong> → D_Mac ≈ <strong>8,5 tahun</strong> (bukan 10! kupon mempercepat).</p>\n<p><strong>Rate +3%</strong>: harga −25% (price risk!), tapi kupon reinvest <strong>+3%</strong> → di tahun ke-8,5 keduanya <strong>impas</strong>; di tahun 10: <strong>Rp1M terpenuhi</strong> ✓.</p>\n<p><strong>Kesalahan bendahara</strong>: pikir 'jatuh tempo = aman' — benar <em>kebetulan</em> (kupon kecil). Imunisasi <em>presisi</em> = match <strong>duration</strong>, bukan maturity!</p>"}, 'charts': []}, {'id': 'struktur', 'toc': 'Ladder/Barbell/Bullet', 'title': 'Ladder, Barbell, Bullet — Arsitektur', 'body': '<p><strong>Definisi.</strong> <strong>Ladder</strong>: jatuh tempo <em>merata</em> (1,2,3...10 thn) — reinvestasi rutin, <em>risiko reinvestment rendah</em>. <strong>Bullet</strong>: fokus di <em>satu</em> titik (10 thn) — untuk kewajiban tunggal. <strong>Barbell</strong>: ujung <em>pendek + panjang</em> — likuiditas + yield; <em>convexity tinggi</em> (untung saat volatilitas!).</p>\n<p><strong>Pilih</strong>: kewajiban tunggal → bullet/imunisasi; arus kas rutin → ladder; view volatilitas → barbell.</p>', 'formulas': [], 'intuisi': 'Ladder seperti <strong>tangga</strong>: tiap anak tangga (jatuh tempo) memberi pijakan kas rutin. Barbell seperti <strong>barbel</strong>: berat di dua ujung — stabil di tengah? Tidak — <em>fleksibel</em>: ujung pendek = kas cepat, ujung panjang = yield.', 'kapan': 'Ladder: dana darurat institusi, arus kas rutin. Barbell: antisipasi volatilitas rate.', 'worked': {'title': '📐 Contoh: Ladder Rp500jt (klik untuk buka)', 'body': '<p>Rp500jt dibagi 5: Rp100jt × (1,2,3,4,5 tahun). Tiap tahun <strong>Rp100jt jatuh tempo</strong> → belanjakan atau <strong>reinvestasi ke 5 tahun</strong> (ladder berjalan).</p>\n<p><strong>Rate naik</strong>: reinvestasi di yield <em>lebih tinggi</em> ✓ (lawan reinvestment risk). <strong>Rate turun</strong>: 4 rung masih terkunci yield lama ✓.</p>\n<p><strong>Ladder = dollar-cost averaging-nya obligasi.</strong></p>'}, 'charts': [{'data': '[{x: ["1thn","2thn","3thn","4thn","5thn"], y: [100,100,100,100,100], type: "bar", marker: {color: "#2a7de1"}, name: "ladder"}, {x: ["1thn","2thn","3thn","4thn","5thn"], y: [250,0,0,0,250], type: "bar", marker: {color: "#e8a838"}, name: "barbell"}]', 'title': 'Ladder vs barbell: distribusi jatuh tempo (Rp jt)', 'layout': '{xaxis: {title: "Jatuh tempo"}, yaxis: {title: "Rp jt"}, barmode: "group", showlegend: true}', 'cara': 'Biru = ladder (merata); kuning = barbell (ujung-ujung).', 'interpretasi': 'Ladder: <strong>arus kas tiap tahun</strong> — reinvestasi disiplin. Barbell: <strong>likuiditas</strong> (1 thn) + <strong>yield</strong> (5 thn) + <strong>convexity</strong> lebih tinggi (menang saat rate bergejolak). Pilih sesuai <em>kebutuhan kas</em>, bukan tebakan rate.'}]}, {'id': 'aktif', 'toc': 'Strategi Aktif', 'title': 'Strategi Aktif — Berburu di Pasar Obligasi', 'body': '<p><strong>Definisi.</strong> <strong>Rate anticipation</strong>: ubah duration (panjang saat rate turun). <strong>Spread strategies</strong>: rotasi <em>sektor/kualitas</em> (IG ↔ HY) saat spread murah/mahal. <strong>Credit rotation</strong>: naik-turun kualitas mengikuti siklus.</p>\n<p><strong>Kunci</strong>: aktif = <strong>tracking error</strong> vs benchmark (PM-B5!) — ukur dengan <strong>information ratio</strong>.</p>', 'formulas': [], 'intuisi': 'Strategi aktif obligasi seperti <strong>berselancar</strong>: rate anticipation = membaca ombak (siklus); spread = memilih papan (sektor murah). Peselancar hebat <em>jatuh juga</em> — ukurannya <strong>konsistensi</strong> (IR), bukan satu ombak besar.', 'kapan': 'Mandat aktif dengan benchmark jelas; disiplin tracking error.', 'worked': {'title': '📐 Contoh: Rotasi kredit (klik untuk buka)', 'body': '<p>Spread HY 800bps (krisis, historis 500) → <strong>murah</strong> → overweight HY.</p>\n<p>Pemulihan: spread → 450bps → capital gain + kupon tinggi = <strong>outperform 5%</strong>.</p>\n<p><strong>Disiplin</strong>: kembali netral saat spread &lt; 400 (mahal). Tanpa aturan jual = <strong>serakah</strong> (PM-C6!).</p>'}, 'charts': []}], 'myths': [{'t': 'Obligasi jatuh tempo 10 tahun = imunisasi kewajiban 10 tahun.', 'benar': "Yang harus match = <strong>Macaulay duration</strong> (≈ 8,5 thn untuk kupon bond!), bukan maturity. 'Kebetulan aman' ≠ imunisasi. Dan duration <strong>bergeser</strong> → butuh <strong>rebalancing berkala</strong>. Imunisasi = proses, bukan sekali beli."}, {'t': 'Obligasi = aman, tidak perlu strategi.', 'benar': "2022: obligasi global <strong>−16%</strong> (terburuk sepanjang sejarah!). Risiko rate, kredit, likuiditas = nyata. 'Aman' hanya jika <strong>dipegang sampai maturity</strong> (dan penerbit tidak default!). Portofolio obligasi butuh <em>strategi</em> sama seriusnya dengan saham."}], 'tips': ['<strong>Match duration, bukan maturity.</strong> Tiap kewajiban: hitung horizon → cari D_Mac aset yang sama → rebalance tahunan. Satu baris di IPS menghemat bencana.', '<strong>Ladder untuk kas rutin, bullet untuk janji tunggal.</strong> Jangan pakai barbell jika butuh kas tiap tahun — arsitektur mengikuti <em>kebutuhan</em>, bukan <em>ramalan</em>.'], 'labs': [{'heading': 'Pemeriksa Imunisasi', 'intro': 'Cek apakah portofolio obligasi terimunisasi terhadap kewajiban.', 'title': 'Lab 1 — Pemeriksa Imunisasi', 'hint': 'Ubah DUR_ASET 8.5 → 5.0 (terlalu pendek). Status berubah — rebalance dibutuhkan!', 'code': '# Pemeriksa imunisasi: D_aset vs horizon kewajiban\nDUR_ASET = 8.5    # Macaulay duration portofolio (ubah!)\nHORIZON = 10      # tahun kewajiban\nTOL = 0.5\n\nselisih = abs(DUR_ASET - HORIZON)\nprint(f"Duration aset : {DUR_ASET} thn")\nprint(f"Horizon       : {HORIZON} thn")\nprint(f"Selisih       : {selisih:.1f} thn")\nif selisih <= TOL:\n    print("TERIMUNISASI: price risk ~ reinvestment risk.")\nelse:\n    arah = "terlalu PENDEK (reinvestment risk dominan)" if DUR_ASET < HORIZON else "terlalu PANJANG (price risk dominan)"\n    print(f"BELUM: duration {arah}. Rebalance!")\nprint("\\nImunisasi melindungi dari PARALLEL shift saja.")\n'}, {'heading': 'Pembangun Ladder', 'intro': 'Bangun ladder dan simulasikan arus kas tahunannya.', 'title': 'Lab 2 — Pembangun Ladder', 'hint': 'Ubah N_RUNG 5 → 10. Arus kas makin halus — ladder berjalan!', 'code': '# Pembangun ladder obligasi\nTOTAL = 500  # Rp jt\nN_RUNG = 5   # jumlah rung (ubah!)\nYIELD = 0.07\n\nper_rung = TOTAL / N_RUNG\nprint(f"Ladder {N_RUNG} rung x Rp{per_rung:.0f}jt @ {YIELD:.0%}")\nprint()\nkas_tahunan = 0\nfor t in range(1, N_RUNG+1):\n    jatuh = per_rung\n    kupon = per_rung * YIELD\n    kas_tahunan += kupon\n    print(f"  Tahun {t}: jatuh tempo Rp{jatuh:.0f}jt + kupon Rp{kupon:.0f}jt")\nprint()\nprint(f"Arus kas kupon/tahun: Rp{kas_tahunan:.0f}jt")\nprint("Tiap jatuh tempo: belanjakan ATAU reinvestasi ke rung terjauh.")\n'}], 'decisions': [{'kondisi': 'Kewajiban pasti tunggal', 'pakai': 'Imunisasi (duration match) / bullet', 'alasan': 'Kunci pembayaran.', 'contoh': 'Beasiswa 10 thn.'}, {'kondisi': 'Butuh kas rutin', 'pakai': 'Ladder', 'alasan': 'Arus kas + reinvestasi disiplin.', 'contoh': 'Dana operasional yayasan.'}, {'kondisi': 'Antisipasi volatilitas rate', 'pakai': 'Barbell (convexity)', 'alasan': 'Menang saat gejolak.', 'contoh': 'Mandat aktif.'}, {'kondisi': 'Spread HY murah (krisis)', 'pakai': 'Rotasi kredit overweight HY + aturan jual', 'alasan': 'Mean-reversion spread.', 'contoh': '800bps → 450bps.'}], 'rule10': '<ol><li><strong>Match duration</strong>, bukan maturity.</li><li><strong>Rebalance</strong> imunisasi berkala.</li><li><strong>Arsitektur</strong> ikut kebutuhan kas.</li><li><strong>Disiplin jual</strong> di strategi aktif.</li></ol>', 'case': {'toc': 'Mini-Case: Beasiswa Rp1M', 'title': 'Janji 10 Tahun, Rate Naik 3%', 'body': '<p>Yayasan: kewajiban Rp1M 10 tahun. Obligasi 10 tahun, rate +3% → harga −25%.</p>', 'q': '(a) Apakah Rp1M terancam? (b) Apa kesalahan konsep bendahara? (c) Desain imunisasi yang benar?', 'pembahasan': '<p>(a) <strong>Tidak</strong> (jika dipegang): price risk vs reinvestment risk impas di duration; kupon reinvest lebih tinggi → Rp1M <strong>terpenuhi</strong>.</p>\n<p>(b) <strong>Match maturity, bukan duration</strong> (D_Mac ≈ 8,5 thn ≠ 10 thn) + tidak ada rencana rebalance.</p>\n<p>(c) <strong>D_aset = 10</strong> (kombinasi obligasi), <strong>rebalance tahunan</strong>, lindungi hanya parallel shift (komunikasikan batasnya!).</p>'}, 'quiz': [{'q': 'Imunisasi yang benar: match apa?', 'options': ['Maturity = horizon', 'Macaulay duration = horizon', 'Kupon = yield', 'Harga = PV'], 'correct': 1, 'why': 'Benar: D_Mac = titik impas price vs reinvestment risk. Maturity ≠ duration untuk coupon bond.'}, {'q': 'Rate naik 3%, obligasi 10 tahun. Bagi pemegang sampai maturity?', 'options': ['Rugi 25%', 'Kewajiban tetap terpenuhi (kupon reinvest lebih tinggi)', 'Default', 'Tidak ada efek'], 'correct': 1, 'why': 'Benar: jika tidak dijual, arus kas kontraktual tetap. Panik jual = wujudkan rugi.'}, {'q': 'Butuh kas tiap tahun. Arsitektur?', 'options': ['Bullet', 'Ladder', 'Barbell', 'Kas saja'], 'correct': 1, 'why': 'Benar: ladder = jatuh tempo merata → arus kas rutin + reinvestasi disiplin.'}, {'q': 'Imunisasi melindungi dari?', 'options': ['Semua risiko', 'Parallel shift yield curve', 'Default', 'Inflasi'], 'correct': 1, 'why': 'Benar: hanya parallel shift. Twist butuh key-rate duration; default butuh kredit analysis.'}, {'q': 'Duration imunisasi setelah 1 tahun?', 'options': ['Tetap', 'Bergeser — butuh rebalance', 'Nol', 'Naik 1'], 'correct': 1, 'why': 'Benar: duration meleset seiring waktu & pergerakan rate. Imunisasi = proses, bukan sekali beli.'}], 'rangkum': ['<strong>Imunisasi</strong>: D_aset = horizon; price vs reinvestment risk impas.', '<strong>3 teknik</strong>: cash-flow matching, duration matching, horizon matching.', '<strong>Arsitektur</strong>: ladder (kas rutin), bullet (janji tunggal), barbell (convexity).', '<strong>Aktif</strong>: rate anticipation, rotasi spread/kredit + disiplin.', '<strong>Batas</strong>: parallel shift saja; rebalance berkala.', '<strong>Aturan</strong>: match duration bukan maturity; 2022 bukti obligasi bisa −16%.'], 'prev': ['pm-c6-behavioral', 'PM-C6'], 'next': ['pm-c8-equity-portfolio', 'PM-C8']}, {'slug': 'pm-c8-equity-portfolio', 'id': 'PM-C8', 'track': 'Portfolio Management', 'title_html': 'Equity Portfolio:<br/>Aktif, Pasif & Smart Beta', 'title_plain': 'Equity Portfolio: Active vs Passive, Smart Beta, Factor', 'chapter_summary': 'CFA L3 ekuitas: aktif vs pasif (tracking error, information ratio), smart beta & factor tilts, core-satellite, dan completeness fund. Lab kalkulator IR/TE & simulator factor tilt.', 'tujuan': ['Menjelaskan trade-off aktif vs pasif via information ratio.', 'Menghitung tracking error dan information ratio.', 'Menjelaskan smart beta dan premi faktor.', 'Merancang struktur core-satellite.'], 'story_title': 'Cerita: Taruhan Rp1 Miliar Warren Buffett', 'story': "<p><strong>2008</strong>: Warren Buffett bertaruh <strong>USD 1 juta</strong> — <em>indeks S&amp;P 500</em> akan mengalahkan <em>5 fund-of-hedge-funds</em> dalam 10 tahun. Wall Street tertawa. <strong>2017</strong>: indeks <strong>+125%</strong>, hedge funds <strong>+36%</strong>. Buffett menang telak — untuk amal.</p>\n<p>Twist-nya: yang dikalahkan bukan 'orang bodoh' — melainkan <strong>manajer terbaik dengan fee 2-and-20</strong>. <strong>Biaya = kepastian, alpha = harapan.</strong> Tapi cerita tidak berhenti di 'pasif selalu menang' — ada <strong>jalan ketiga</strong>: smart beta. Lesson ini: memilih senjata dengan sadar.</p>", 'concepts': [{'id': 'aktifpasif', 'toc': 'Aktif vs Pasif', 'title': 'Aktif vs Pasif — Perang Abadi', 'body': '<p><strong>Definisi.</strong> <strong>Pasif</strong>: replikasi indeks (TE ≈ 0, fee 0,05–0,2%). <strong>Aktif</strong>: menyimpang untuk alpha (TE &gt; 0, fee 0,5–2%). <strong>Information ratio</strong>: IR = active return / tracking error — <strong>alpha per unit risiko aktif</strong>. <strong>Fundamental law</strong>: IR ≈ IC × √Breadth.</p>\n<p><strong>Aturan</strong>: aktif hanya jika <strong>IR ekspektasi × keyakinan &gt; fee</strong>.</p>', 'formulas': [{'math': 'IR = \\frac{R_p - R_b}{TE} \\quad;\\quad TE = \\sigma(R_p - R_b)', 'symbols': ['<Tex math={String.raw`TE`} />: tracking error (volatilitas active return)', 'IR &gt; 0,5: baik; IR &gt; 1: luar biasa (sangat jarang!)', 'Fundamental law: <Tex math={String.raw`IR \\approx IC \\times \\sqrt{Breadth}`} />', 'IC = skill per taruhan; Breadth = jumlah taruhan independen']}], 'intuisi': 'IR seperti <strong>rasio nilai-vs-gaduh</strong>: aktif = berteriak (TE) berharap didengar (alpha). IR 0,5 = suara jernih; IR negatif = <strong>bayar mahal untuk diganggu</strong>. Buffett: 5 hedge funds = bayar 2-and-20 untuk <em>kebisingan</em>.', 'kapan': 'Pilih manajer: tuntut IR 3–5 tahun, bukan return mentah.', 'worked': {'title': '📐 Contoh: Audit manajer (klik untuk buka)', 'body': '<p>Manajer: active return +2%/thn, TE 8%, fee 1,5%. <strong>IR</strong> = 2/8 = <strong>0,25</strong> (lemah!). Net active = 2 − 1,5 = <strong>0,5%</strong>.</p>\n<p><strong>Verdict</strong>: bayar 1,5% untuk 0,5% net dengan gejolak 8% → <strong>pecat</strong> (atau nego fee!).</p>\n<p><strong>Alternatif</strong>: indeks (fee 0,1%) + <strong>smart beta value</strong> (fee 0,3%, premi historis 2%) → ekspektasi net <strong>+1,6%</strong> dengan TE 4%.</p>'}, 'charts': []}, {'id': 'smartbeta', 'toc': 'Smart Beta & Faktor', 'title': 'Smart Beta — Jalan Ketiga', 'body': "<p><strong>Definisi.</strong> <strong>Smart beta</strong>: indeks <em>berbobot faktor</em> (bukan kapitalisasi) — <strong>value, momentum, quality, low-vol, size</strong> — aturan transparan, fee murah (0,2–0,4%). <strong>Premi faktor</strong>: return lebih historis dengan <em>penjelasan risiko/perilaku</em>.</p>\n<p><strong>Jebakan</strong>: <em>factor crowding</em>, <em>drawdown panjang</em> (value 2007–2020!), <em>data mining</em> (400+ 'faktor' palsu!).</p>", 'formulas': [], 'intuisi': 'Smart beta seperti <strong>resep masakan terbuka</strong>: bukan koki misterius (aktif mahal), bukan mie instan (pasif murni) — <strong>resep teruji</strong> (faktor) yang bisa dimasak sendiri murah. Tapi resep <em>bisa basi</em> (crowding) — cicipi berkala!', 'kapan': 'Inti portofolio murah dengan tilt sistematis; diversifikasi sumber return.', 'worked': {'title': '📐 Contoh: Musim dingin value (klik untuk buka)', 'body': '<p>Value factor: premi historis ~3%/thn. <strong>2007–2020</strong>: underperform growth <strong>13 tahun</strong>! Investor menyerah di 2019 — <strong>tepat sebelum</strong> value rebound +30% (2021–2022).</p>\n<p><strong>Pelajaran</strong>: premi faktor = <strong>kompensasi rasa sakit</strong>. Jika tidak tahan 10 tahun menderita, <strong>jangan ambil premia</strong>. Faktor butuh <em>keyakinan + horizon</em>, bukan backtest cantik.</p>'}, 'charts': [{'data': '[{x: ["Value","Momentum","Quality","Low-vol","Size"], y: [3.0,4.0,2.5,1.5,2.0], type: "bar", marker: {color: ["#2a7de1","#16a34a","#e8a838","#94a3b8","#8b5cf6"]}, text: ["3,0%","4,0%","2,5%","1,5%","2,0%"], textposition: "outside"}]', 'title': 'Premi faktor historis (ilustrasi, %/tahun)', 'layout': '{xaxis: {title: "Faktor"}, yaxis: {title: "Premi (%/tahun)"}, showlegend: false}', 'cara': 'Tinggi batang = premi historis rata-rata (jangka sangat panjang).', 'interpretasi': 'Premi <strong>nyata tapi tidak gratis</strong>: datang dengan <strong>drawdown multi-tahun</strong> (value 13 tahun!). Angka ini <em>rata-rata 100 tahun</em> — dekade Anda bisa nol. Ambil faktor hanya dengan <strong>horizon &amp; keyakinan</strong> yang cukup untuk bertahan. (Ilustrasi; premi bervariasi per periode/definisi.)'}]}, {'id': 'coresat', 'toc': 'Core-Satellite', 'title': 'Core-Satellite — Struktur Pemenang', 'body': '<p><strong>Definisi.</strong> <strong>Core</strong> (70–90%): pasif/smart beta murah — <em>beta</em> efisien. <strong>Satellite</strong> (10–30%): aktif terkonsentrasi — <em>alpha</em> berburu. <strong>Completeness fund</strong>: satelit yang <em>melengkapi</em> bias core (mis. core large-cap → satelit small-cap).</p>\n<p><strong>Manfaat</strong>: biaya total rendah, risiko aktif <em>terkendali</em>, tetap ada peluang alpha.</p>', 'formulas': [], 'intuisi': 'Core-satellite seperti <strong>tim sepak bola</strong>: core = <strong>bek &amp; gelandang</strong> (solid, murah, jarang bikin gol bunuh diri); satellite = <strong>striker</strong> (mahal, inkonsisten, penentu kemenangan). Tim <em>semua striker</em> = kebobolan (biaya) banyak.', 'kapan': 'Struktur default portofolio ekuitas institusi/individu canggih.', 'worked': {'title': '📐 Contoh: Struktur Rp10M (klik untuk buka)', 'body': '<p><strong>Core 80%</strong> (Rp8M): indeks + smart beta value (fee 0,2%). <strong>Satellite 20%</strong> (Rp2M): 2 manajer aktif terkonsentrasi (fee 1%).</p>\n<p><strong>Fee total</strong> = 0,8×0,2% + 0,2×1% = <strong>0,36%</strong> (vs 1% all-aktif).</p>\n<p><strong>Hasil</strong>: beta murah + 2 tembakan alpha. Jika satelit gagal 5 tahun → <strong>potong</strong> (aturan tertulis!). Struktur <strong>memaksa disiplin</strong>.</p>'}, 'charts': []}], 'myths': [{'t': 'Manajer aktif dengan return 15% = hebat, layak fee 2%.', 'benar': 'Tanya: <strong>benchmark return berapa? TE berapa? IR berapa? Net setelah fee?</strong> Return 15% saat indeks 16% = <strong>gagal</strong> (active −1%!). Buffett membuktikan: fee 2-and-20 + IR rendah = <strong>pasti kalah</strong> jangka panjang. <strong>IR net, bukan return mentah.</strong>'}, {'t': "Smart beta = return gratis dari 'anomali'.", 'benar': 'Premi = <strong>kompensasi rasa sakit</strong> (value menderita 13 tahun!). 400+ faktor = mostly <strong>data mining</strong>. Hanya faktor dengan <em>logika ekonomi</em> + <em>out-of-sample</em> yang layak — dan tetap butuh <strong>horizon dekade</strong>.'}], 'tips': ['<strong>Hitung IR net sebelum kagum.</strong> (Active return − fee) / TE. Di bawah 0,3 konsisten = pecat/nego. Satu rumus menghemat miliaran fee.', "<strong>Tulis aturan 'pecat' satelit di awal.</strong> 'Underperform 5 tahun → review; 7 tahun → potong.' Aturan saat tenang &gt; debat saat emosi (PM-C6!)."], 'labs': [{'heading': 'Kalkulator IR & TE', 'intro': 'Audit manajer: hitung tracking error & information ratio dari active return.', 'title': 'Lab 1 — Kalkulator IR', 'hint': 'Ubah FEE 0.015 → 0.005 (nego!). IR net membaik — fee = alpha yang pasti!', 'code': '# Information ratio: audit manajer aktif\nimport math\nACTIVE = [0.03, -0.01, 0.04, 0.02, -0.02, 0.05, 0.01, 0.03]  # active return/thn\nFEE = 0.015   # fee tahunan (ubah!)\n\nn = len(ACTIVE)\nmean_a = sum(ACTIVE)/n\nte = math.sqrt(sum((a-mean_a)**2 for a in ACTIVE)/(n-1))\nir_gross = mean_a/te\nir_net = (mean_a - FEE)/te\n\nprint(f"Active return rata2: {mean_a:.2%}")\nprint(f"Tracking error     : {te:.2%}")\nprint(f"IR gross           : {ir_gross:.2f}")\nprint(f"IR net (fee {FEE:.1%}): {ir_net:.2f}")\nprint()\nprint("IR > 0,5 baik; IR net < 0,3 = pertimbangkan pecat/nego.")\nprint("Fee = satu-satunya alpha yang PASTI (untuk manajer!).")\n'}, {'heading': 'Simulator Core-Satellite', 'intro': 'Bandingkan fee & hasil struktur core-satellite vs all-aktif.', 'title': 'Lab 2 — Simulator Core-Satellite', 'hint': 'Ubah SATELIT 0.2 → 0.5. Fee total naik — alpha harus lebih besar untuk impas!', 'code': '# Core-satellite: fee total & ekspektasi\nSATELIT = 0.2      # bobot satelit (ubah!)\nFEE_CORE, FEE_SAT = 0.002, 0.01\nALPHA_SAT = 0.02   # ekspektasi alpha satelit (sebelum fee)\n\nfee_total = (1-SATELIT)*FEE_CORE + SATELIT*FEE_SAT\nalpha_net = SATELIT*(ALPHA_SAT - FEE_SAT) - (1-SATELIT)*FEE_CORE\nfee_allaktif = 0.01\n\nprint(f"Fee core-satellite: {fee_total:.2%}")\nprint(f"Fee all-aktif     : {fee_allaktif:.2%}")\nprint(f"Hemat             : {fee_allaktif - fee_total:.2%}/tahun")\nprint(f"Alpha net ekspektasi: {alpha_net:.2%}")\nprint()\nprint("Satelit harus hasilkan alpha > fee-nya SENDIRI.")\nprint("Jika tidak -> perbesar core (atau full pasif).")\n'}], 'decisions': [{'kondisi': 'Pilih manajer aktif', 'pakai': 'IR net 3–5 tahun &gt; 0,3', 'alasan': 'Bukti, bukan cerita.', 'contoh': 'Audit Lab 1.'}, {'kondisi': 'Tidak ada keyakinan alpha', 'pakai': 'Pasif penuh (fee 0,1%)', 'alasan': 'Biaya pasti, alpha harapan.', 'contoh': 'Buffett bet.'}, {'kondisi': 'Mau tilt sistematis murah', 'pakai': 'Smart beta (faktor berlogika)', 'alasan': 'Jalan ketiga.', 'contoh': 'Value/quality 0,3%.'}, {'kondisi': 'Struktur default', 'pakai': 'Core-satellite + aturan pecat', 'alasan': 'Disiplin + peluang.', 'contoh': '80/20.'}], 'rule10': '<ol><li><strong>IR net</strong>, bukan return mentah.</li><li><strong>Fee</strong> = alpha pasti (buat manajer).</li><li><strong>Faktor</strong> butuh horizon dekade.</li><li><strong>Aturan pecat</strong> tertulis.</li></ol>', 'case': {'toc': 'Mini-Case: Taruhan Buffett', 'title': 'Rp1 Miliar untuk Amal', 'body': '<p>Buffett (2008): S&amp;P 500 vs 5 fund-of-hedge-funds, 10 tahun. Hasil: +125% vs +36%.</p>', 'q': "(a) Mengapa hedge funds kalah telak? (b) Apakah ini bukti 'pasif selalu menang'? (c) Struktur apa yang menggabungkan pelajaran ini?", 'pembahasan': "<p>(a) <strong>Fee 2-and-20</strong> = alpha negatif pasti; fund-of-funds = <strong>fee ganda</strong>; IR net hancur. Biaya = kepastian.</p>\n<p>(b) <strong>Tidak.</strong> Ini bukti 'biaya tinggi + diversifikasi berlebihan = kalah'. Manajer <em>terkonsentrasi</em> ber-IR tinggi tetap ada — <strong>jarang</strong>.</p>\n<p>(c) <strong>Core-satellite</strong>: core pasif murah (pelajaran Buffett) + satelit aktif <em>selektif</em> ber-IR terbukti + <strong>aturan pecat</strong>.</p>"}, 'quiz': [{'q': 'Active return +2%, TE 8%. IR?', 'options': ['0,16', '0,25 (lemah)', '0,5', '1,0'], 'correct': 1, 'why': 'Benar: 2/8 = 0,25. Net setelah fee 1,5% → 0,06. Pecat/nego!'}, {'q': 'Fundamental law: IR ≈ ?', 'options': ['IC + Breadth', 'IC × √Breadth', 'TE × fee', 'Return − risiko'], 'correct': 1, 'why': 'Benar: skill per taruhan × akar jumlah taruhan independen. Banyak taruhan kecil &gt; sedikit taruhan besar.'}, {'q': 'Value underperform 13 tahun (2007–2020). Pelajaran?', 'options': ['Faktor mati', 'Premi = kompensasi rasa sakit; butuh horizon dekade', 'Ganti faktor tiap tahun', 'Faktor scam'], 'correct': 1, 'why': 'Benar: yang menyerah 2019 melewatkan rebound +30%. Tanpa keyakinan horizon, jangan ambil premi.'}, {'q': 'Core 80% (fee 0,2%), satelit 20% (fee 1%). Fee total?', 'options': ['1%', '0,36%', '0,6%', '1,2%'], 'correct': 1, 'why': 'Benar: 0,8×0,2%+0,2×1% = 0,36%. Struktur hemat + tetap ada tembakan alpha.'}, {'q': 'Manajer return 15%, indeks 16%, fee 2%. Verdict?', 'options': ['Hebat', 'Gagal: active −1% net −3%', 'Lumayan', 'Tahan'], 'correct': 1, 'why': 'Benar: return mentah menipu. Active −1%, net −3%! IR net = ukuran kebenaran.'}], 'rangkum': ['<strong>IR</strong> = active return / TE; IR net &gt; 0,5 = baik.', '<strong>Fundamental law</strong>: IC × √Breadth.', '<strong>Buffett bet</strong>: biaya = kepastian, alpha = harapan.', '<strong>Smart beta</strong>: jalan ketiga; premi = kompensasi rasa sakit.', '<strong>Core-satellite</strong>: 80/20 + aturan pecat tertulis.', '<strong>Aturan</strong>: kagum pada IR net, bukan return mentah.'], 'prev': ['pm-c7-fixed-income-portfolio', 'PM-C7'], 'next': ['pm-c9-derivatives-overlay', 'PM-C9']}, {'slug': 'pm-c9-derivatives-overlay', 'id': 'PM-C9', 'track': 'Portfolio Management', 'title_html': 'Derivatives Overlay:<br/>Hedging & Portable Alpha', 'title_plain': 'Derivatives Overlay: Hedging, Currency Overlay, Portable Alpha', 'chapter_summary': 'CFA L3 derivatif: equity overlay (protective put, collar, covered call), currency overlay & hedge ratio, portable alpha, dan completion portfolio. Lab kalkulator collar & hedge ratio optimal.', 'tujuan': ['Menjelaskan 3 equity overlay dan trade-off-nya.', 'Menghitung hedge ratio optimal untuk eksposur valas.', 'Menjelaskan portable alpha dan completion.', 'Memilih overlay sesuai objective.'], 'story_title': "Cerita: Rp50 Miliar yang 'Diasuransikan' Rp500 Juta", 'story': "<p><strong>Dana pensiun</strong> kelola <strong>Rp50 miliar</strong> saham. <strong>Januari 2020</strong>: CIO gelisah (valuasi tinggi, virus misterius). Beli <strong>protective put 3 bulan</strong>: premi <strong>Rp500 juta</strong> (1%). <strong>Maret</strong>: pasar <strong>−35%</strong> → put meledak → kerugian terpotong <strong>Rp12 miliar</strong>.</p>\n<p>Twist-nya: dewan <em>protes</em> — 'Rp500jt hangus jika pasar naik!' CIO: <strong>'Asuransi rumah juga hangus jika tidak kebakaran.'</strong> Tahun itu put <em>tidak</em> hangus — ia <strong>menyelamatkan</strong> funded ratio. Lesson ini: derivatif sebagai <em>asuransi</em>, bukan <em>spekulasi</em>.</p>", 'concepts': [{'id': 'equityoverlay', 'toc': 'Equity Overlay', 'title': 'Equity Overlay — Asuransi Portofolio', 'body': '<p><strong>Definisi.</strong> <strong>Protective put</strong>: beli put → batasi downside, <em>bayar premi</em>. <strong>Covered call</strong>: jual call → <em>terima premi</em>, korbankan upside. <strong>Collar</strong>: beli put + jual call → <strong>koridor</strong> (downside lindung, upside dibatasi) — sering <strong>zero-cost</strong>!</p>\n<p><strong>Trade-off</strong>: tidak ada makan siang — proteksi <em>selalu</em> dibayar (premi atau upside).</p>', 'formulas': [{'math': '\\text{Collar: } S + P(K_1) - C(K_2), \\quad K_1 < S < K_2', 'symbols': ['<Tex math={String.raw`P(K_1)`} />: long put strike bawah (lantai)', '<Tex math={String.raw`C(K_2)`} />: short call strike atas (plafon)', 'Zero-cost: premi put ≈ premi call', 'Payoff terkunci di <Tex math={String.raw`[K_1, K_2]`} />']}], 'intuisi': 'Collar seperti <strong>koridor hotel</strong>: put = <strong>dinding bawah</strong> (tidak jatuh), call yang dijual = <strong>plafon</strong> (tidak bisa terbang). Tinggal di koridor = <strong>tenang</strong>. Harganya: tidak bisa lihat bintang (upside besar).', 'kapan': 'Lindungi funded ratio / lock-in gain; zero-cost collar untuk institusi.', 'worked': {'title': '📐 Contoh: Collar dana pensiun (klik untuk buka)', 'body': '<p>Saham Rp50M (harga 100). Beli put K=90 (premi 3), jual call K=110 (premi 3) → <strong>zero-cost</strong>.</p>\n<p><strong>Skenario</strong>: jatuh ke 70 → put bayar 20 → nilai <strong>90 − 0 = 90%</strong> (rugi maks 10%). Naik ke 130 → call dieksekusi → nilai <strong>110%</strong> (cuan maks 10%).</p>\n<p><strong>Hasil Maret 2020</strong>: pasar −35% → portofolio <strong>−10%</strong> (bukan −35%!). Funded ratio <strong>selamat</strong>. Dewan yang protes kini diam.</p>'}, 'charts': [{'data': '[{x: [70,80,90,100,110,120,130], y: [90,90,90,100,110,110,110], type: "scatter", mode: "lines+markers", marker: {color: "#2a7de1"}, line: {width: 3}, name: "collar"}, {x: [70,80,90,100,110,120,130], y: [70,80,90,100,110,120,130], type: "scatter", mode: "lines", line: {dash: "dash", color: "#94a3b8"}, name: "tanpa lindung"}]', 'title': 'Payoff collar (K1=90, K2=110) vs tanpa lindung', 'layout': '{xaxis: {title: "Harga saham saat expiry"}, yaxis: {title: "Nilai portofolio"}, showlegend: true}', 'cara': 'Biru = collar; abu putus-putus = tanpa lindung. Sumbu-x = harga akhir.', 'interpretasi': 'Collar <strong>memotong kedua ekor</strong>: rugi maks 10% (lantai 90), cuan maks 10% (plafon 110). Tanpa lindung = garis 45° (bebas, berisiko). Pilih collar saat <strong>ketenangan &gt; lotere</strong> — mis. lindungi funded ratio institusi.'}]}, {'id': 'currency', 'toc': 'Currency Overlay', 'title': 'Currency Overlay — Menjinakkan Valas', 'body': '<p><strong>Definisi.</strong> Aset global = <strong>return aset + return valas</strong>. <strong>Hedge ratio</strong>: % eksposur valas yang dilindungi (0–100%). <strong>Hedge optimal</strong>: h* = ρ × (σ_aset/σ_fx) — dari regresi! <strong>Cross-hedge</strong>: lindungi dengan <em>proxy</em> saat forward tidak tersedia.</p>\n<p><strong>Keputusan</strong>: hedge jika valas = <strong>risiko tanpa premi</strong> (jangka pendek); biarkan jika <strong>diversifikasi</strong> (jangka panjang) atau <strong>biaya carry mahal</strong>.</p>', 'formulas': [{'math': 'h^* = \\rho_{A,FX} \\frac{\\sigma_A}{\\sigma_{FX}}', 'symbols': ['<Tex math={String.raw`h^*`} />: hedge ratio optimal (regresi return aset thd FX)', 'Jika <Tex math={String.raw`h^*`} /> = 0,6 → hedge 60% eksposur', 'Biaya hedge ≈ selisih suku bunga (covered interest parity!)', 'Review: korelasi berubah → hedge ratio berubah']}], 'intuisi': "Currency overlay seperti <strong>sabuk pengaman</strong>: perjalanan (investasi global) tetap jalan; sabuk (hedge) hanya mengurangi <em>cedera</em> (volatilitas FX). Tidak pakai sabuk karena 'mahal' = berhemat di tempat salah.", 'kapan': 'Eksposur global material; putuskan hedge ratio per mata uang.', 'worked': {'title': '📐 Contoh: Hedge USD/IDR (klik untuk buka)', 'body': '<p>Reksadana USD Rp10M. ρ(aset, USDIDR) = 0,3; σ_aset = 15%, σ_fx = 8%.</p>\n<p><strong>h*</strong> = 0,3 × 15/8 = <strong>0,56</strong> → hedge <strong>56%</strong> via forward USDIDR.</p>\n<p><strong>Biaya</strong>: (BI rate − Fed rate) ≈ 2%/tahun → <strong>Rp112jt</strong> untuk proteksi Rp5,6M. <strong>Worth it?</strong> Jika volatilitas IDR mengganggu IPS → ya.</p>'}, 'charts': []}, {'id': 'portable', 'toc': 'Portable Alpha', 'title': 'Portable Alpha — Memindahkan Keahlian', 'body': "<p><strong>Definisi.</strong> <strong>Portable alpha</strong>: pisahkan <em>alpha</em> (skill manajer A) dari <em>beta</em> (eksposur pasar B) via derivatif — 'pindahkan' alpha ke mana pun. <strong>Completion portfolio</strong>: overlay yang <em>melengkapi</em> bias tidak disengaja (mis. semua manajer large-cap → tambah small-cap futures).</p>\n<p><strong>Syarat</strong>: alpha <em>benar-benar portable</em> (tidak terikat beta asal!) + pasar futures <em>likuid</em>.</p>", 'formulas': [], 'intuisi': 'Portable alpha seperti <strong>koki bintang yang bisa masak di dapur mana pun</strong>: skill (alpha) dibawa; dapur (beta pasar) disewa via futures. Completion = <strong>bumbu pelengkap</strong> agar hidangan (portofolio total) seimbang.', 'kapan': 'Manajer alpha terbaik ada di kelas aset yang tidak dibutuhkan.', 'worked': {'title': '📐 Contoh: Alpha obligasi → ekuitas (klik untuk buka)', 'body': '<p>Manajer obligasi hebat (alpha +3%) tapi SAA butuh <em>ekuitas</em>. <strong>Portable</strong>: beli manajer obligasi + <strong>jual bond futures + beli equity futures</strong> (swap beta).</p>\n<p><strong>Hasil</strong>: eksposur ekuitas (beta) + alpha obligasi = <strong>keduanya</strong>! Tanpa portable: pilih salah satu.</p>\n<p><strong>Risiko</strong>: basis risk futures + alpha ternyata <em>tidak</em> portable (terikat pasar obligasi!). Uji dulu.</p>'}, 'charts': []}], 'myths': [{'t': 'Derivatif = spekulasi berbahaya. Institusi konservatif harus hindari.', 'benar': 'Derivatif = <strong>alat</strong>; bahaya di <em>tangan</em> &amp; <em>tujuan</em>. Dana pensiun: put <strong>menyelamatkan Rp12M</strong> (2020). <strong>Spekulasi</strong> = naked, leverage liar. <strong>Hedging</strong> = proteksi terukur. Bedakan <em>penggunaan</em>, bukan <em>instrumennya</em>.'}, {'t': 'Hedge 100% selalu terbaik — hilangkan semua risiko valas.', 'benar': '<strong>h* jarang 100%</strong> (contoh: 56%!). Full hedge = <strong>biaya carry penuh</strong> + hilangkan <em>diversifikasi</em> valas jangka panjang. Hedge ratio = <strong>optimisasi</strong>, bukan tombol on/off.'}], 'tips': ['<strong>Harga proteksi saat tenang.</strong> Premi put murah saat VIX rendah (2020 Januari!). Asuransi dibeli <em>sebelum</em> kebakaran — sesudahnya premi 5x lipat. Jadwalkan review overlay tiap kuartal.', "<strong>Zero-cost collar untuk lock-in gain.</strong> Setelah rally besar: collar gratis mengunci keuntungan. 'Biaya'-nya upside — yang <em>sudah</em> dinikmati sebagian. Psikologi: mudah disetujui dewan."], 'labs': [{'heading': 'Kalkulator Collar', 'intro': 'Hitung lantai, plafon, dan biaya bersih collar.', 'title': 'Lab 1 — Kalkulator Collar', 'hint': 'Ubah STRIKE_CALL 110 → 105 (plafon lebih rendah). Premi call naik — bisa zero-cost dengan put lebih jauh!', 'code': '# Kalkulator collar: S + P(K1) - C(K2)\nS = 100\nSTRIKE_PUT, PREMI_PUT = 90, 3\nSTRIKE_CALL, PREMI_CALL = 110, 3   # ubah!\n\nlantai = STRIKE_PUT - (PREMI_PUT - PREMI_CALL)\nplafon = STRIKE_CALL - (PREMI_PUT - PREMI_CALL)\nbiaya_bersih = PREMI_PUT - PREMI_CALL\n\nprint(f"Rugi maksimal : {(1 - lantai/S):.0%} (lantai {lantai})")\nprint(f"Cuan maksimal : {(plafon/S - 1):.0%} (plafon {plafon})")\nprint(f"Biaya bersih  : {biaya_bersih} ({\'ZERO-COST\' if biaya_bersih==0 else \'bayar\' if biaya_bersih>0 else \'terima premi\'})")\nprint()\nprint("Collar = koridor ketenangan. Harga: upside dibatasi.")\n'}, {'heading': 'Kalkulator Hedge Ratio', 'intro': 'Hitung hedge ratio optimal dari korelasi & volatilitas.', 'title': 'Lab 2 — Kalkulator Hedge Ratio', 'hint': 'Ubah RHO 0.3 → 0.8 (korelasi kuat). h* naik — hedge lebih besar!', 'code': '# Hedge ratio optimal: h* = rho * sigma_aset / sigma_fx\nRHO = 0.3          # korelasi aset vs FX (ubah!)\nSIG_ASET = 0.15\nSIG_FX = 0.08\nEKSPOSUR = 10_000  # Rp jt\nCARRY = 0.02       # biaya hedge/tahun\n\nh = RHO * SIG_ASET / SIG_FX\nh = max(0, min(1, h))\nnilai_hedge = EKSPOSUR * h\nbiaya = nilai_hedge * CARRY\n\nprint(f"h* = {h:.0%} -> hedge Rp{nilai_hedge:,.0f}jt")\nprint(f"Biaya carry: Rp{biaya:,.0f}jt/tahun")\nprint()\nprint("h* jarang 100%: optimisasi, bukan on/off.")\nprint("Review berkala: korelasi berubah!")\n'}], 'decisions': [{'kondisi': 'Lindungi downside, pertahankan upside', 'pakai': 'Protective put', 'alasan': 'Asuransi murni.', 'contoh': 'Pre-krisis, funded ratio.'}, {'kondisi': 'Lock-in gain setelah rally', 'pakai': 'Zero-cost collar', 'alasan': 'Gratis, koridor tenang.', 'contoh': 'Dana pensiun 2020.'}, {'kondisi': 'Butuh income, pasar sideways', 'pakai': 'Covered call', 'alasan': 'Premi = income.', 'contoh': 'Overlay rutin.'}, {'kondisi': 'Eksposur valas material', 'pakai': 'Currency overlay (h* optimal)', 'alasan': 'Jinakkan tanpa bunuh diversifikasi.', 'contoh': 'h* = 56%.'}], 'rule10': '<ol><li><strong>Derivatif</strong> = alat; <strong>tujuan</strong> menentukan.</li><li><strong>Proteksi</strong> selalu ada harganya.</li><li><strong>h*</strong> = optimisasi, bukan 100%.</li><li><strong>Beli asuransi</strong> saat tenang.</li></ol>', 'case': {'toc': 'Mini-Case: Put Rp500 Jt', 'title': 'Asuransi yang Menyelamatkan Rp12 M', 'body': "<p>Dana pensiun Rp50M: beli put 3 bulan premi Rp500jt (Jan 2020). Maret: −35% → rugi terpotong Rp12M. Dewan protes 'hangus jika naik'.</p>", 'q': '(a) Jawab protes dewan. (b) Mengapa put, bukan jual saham? (c) Kapan TIDAK perlu overlay?', 'pembahasan': "<p>(a) <strong>'Asuransi rumah juga hangus jika tidak kebakaran.'</strong> Rp500jt = 1% untuk proteksi funded ratio. <em>Ekspektasi</em> premi hangus; <em>nilainya</em> di skenario buruk.</p>\n<p>(b) <strong>Jual saham = ubah SAA</strong> (timing!) + biaya + pajak. Put = <strong>pertahankan SAA + proteksi sementara</strong>. Overlay ≠ alokasi.</p>\n<p>(c) <strong>Horizon sangat panjang + funded surplus besar</strong> → volatilitas = noise. Atau <strong>premi mahal</strong> (VIX tinggi) → collar/parsial.</p>"}, 'quiz': [{'q': 'Collar: beli put K=90 (premi 3), jual call K=110 (premi 3), S=100. Lantai & plafon?', 'options': ['90 & 110 (zero-cost)', '87 & 113', '90 & 107', '93 & 110'], 'correct': 1, 'why': 'Benar: biaya bersih 0 → lantai 90, plafon 110. Koridor ketenangan gratis (bayar dengan upside).'}, {'q': 'ρ=0,3, σ_aset=15%, σ_fx=8%. h*?', 'options': ['100%', '56%', '30%', '0%'], 'correct': 1, 'why': 'Benar: 0,3×15/8 = 0,56. Hedge parsial optimal — bukan on/off.'}, {'q': 'Portable alpha memindahkan?', 'options': ['Beta ke pasar lain', 'Alpha manajer A ke eksposur pasar B via derivatif', 'Risiko ke investor', 'Fee ke manajer'], 'correct': 1, 'why': "Benar: pisahkan alpha dari beta asal, 'tempel' ke beta yang dibutuhkan. Syarat: alpha benar-benar portable!"}, {'q': 'Kapan beli protective put paling murah?', 'options': ['Saat krisis', 'Saat tenang (VIX rendah)', 'Tidak pernah', 'Saat panik'], 'correct': 1, 'why': 'Benar: premi murah saat tenang. Asuransi dibeli sebelum kebakaran — sesudahnya 5x lipat.'}, {'q': 'Covered call cocok saat?', 'options': ['Pasar bullish kuat', 'Sideways + butuh income', 'Krisis', 'Selalu'], 'correct': 1, 'why': 'Benar: jual call = terima premi, korbankan upside. Optimal saat pasar mendatar.'}], 'rangkum': ['<strong>Equity overlay</strong>: put (asuransi), call (income), collar (koridor, zero-cost).', '<strong>Currency overlay</strong>: h* = ρ×σ_A/σ_FX; hedge parsial optimal.', '<strong>Portable alpha</strong>: pindahkan skill via futures; completion melengkapi bias.', '<strong>Prinsip</strong>: derivatif = alat; proteksi ada harganya; beli saat tenang.', '<strong>Overlay ≠ alokasi</strong>: lindungi sementara tanpa ubah SAA.', "<strong>Aturan</strong>: 'asuransi rumah juga hangus jika tidak kebakaran'."], 'prev': ['pm-c8-equity-portfolio', 'PM-C8'], 'next': ['pm-c10-trading-execution', 'PM-C10']}, {'slug': 'pm-c10-trading-execution', 'id': 'PM-C10', 'track': 'Portfolio Management', 'title_html': 'Trading & Execution:<br/>Biaya Tersembunyi', 'title_plain': 'Trading & Execution: Transaction Costs, Implementation Shortfall', 'chapter_summary': 'CFA L3 eksekusi: biaya eksplisit vs implisit (spread, market impact, delay, missed trade), implementation shortfall, dan strategi eksekusi (VWAP, TWAP, arrival price). Lab kalkulator shortfall & simulator VWAP.', 'tujuan': ['Membedakan biaya eksplisit vs implisit.', 'Menghitung implementation shortfall dan komponennya.', 'Menjelaskan trade-off strategi eksekusi.', 'Memilih strategi sesuai urgensi & likuiditas.'], 'story_title': 'Cerita: Rp2 Miliar yang Menguap di Meja Trading', 'story': "<p><strong>Manajer</strong> putuskan beli saham <strong>Rp10 miliar</strong> di Rp1.000. Trader eksekusi <strong>seminggu</strong> (takut 'menggerakkan pasar'). Harga rata-rata dapat: <strong>Rp1.040</strong>. Komisi tercatat: <strong>Rp20 juta</strong> (0,2%). Bos puas: 'biaya kecil!'</p>\n<p>Twist-nya: <strong>biaya sebenarnya = Rp420 juta</strong> (4,2%!) — Rp400jt dari <strong>harga bergerak</strong> selama seminggu (delay + market impact), hanya Rp20jt komisi. <strong>Biaya yang terlihat = 5% dari biaya total.</strong> Lesson ini: mengukur yang tak terlihat.</p>", 'concepts': [{'id': 'biaya', 'toc': 'Biaya Eksplisit vs Implisit', 'title': 'Biaya — Gunung Es', 'body': '<p><strong>Definisi.</strong> <strong>Eksplisit</strong>: komisi, pajak, fee — <em>terlihat</em>. <strong>Implisit</strong>: <em>bid-ask spread</em>, <em>market impact</em> (order sendiri menggerakkan harga), <em>delay</em> (harga bergerak sebelum eksekusi), <em>missed trade</em> (gagal eksekusi = opportunity cost!).</p>\n<p><strong>Aturan</strong>: biaya implisit sering <strong>5–20x</strong> eksplisit untuk order besar!</p>', 'formulas': [], 'intuisi': 'Biaya trading seperti <strong>gunung es</strong>: komisi = <strong>puncak</strong> (terlihat, kecil); spread + impact + delay = <strong>badan es</strong> (tak terlihat, raksasa). Kapal (portofolio) karam oleh <em>yang di bawah</em>, bukan puncaknya.', 'kapan': 'Evaluasi trader/broker: ukur total, bukan komisi.', 'worked': {'title': '📐 Contoh: Bedah Rp420jt (klik untuk buka)', 'body': "<p>Beli Rp10M @ Rp1.000 → eksekusi seminggu @ rata-rata Rp1.040.</p>\n<p><strong>Eksplisit</strong>: komisi Rp20jt (0,2%). <strong>Implisit</strong>: delay (Rp1.000→1.020 sebelum mulai: Rp200jt) + market impact (1.020→1.040: Rp200jt).</p>\n<p><strong>Total Rp420jt (4,2%)</strong> — 21x komisi! <strong>Keputusan 'hati-hati'</strong> (seminggu) justru <em>termahal</em>. Eksekusi cepat 1 hari mungkin hanya Rp150jt total.</p>"}, 'charts': []}, {'id': 'shortfall', 'toc': 'Implementation Shortfall', 'title': 'Implementation Shortfall — Kebenaran Pahit', 'body': '<p><strong>Definisi.</strong> <strong>Implementation shortfall</strong> = return <em>paper portfolio</em> (keputusan) − return <em>real portfolio</em> (eksekusi). <strong>Komponen</strong>: delay + market impact + missed trade − <em>penghematan</em> (jika harga bergerak menguntungkan).</p>\n<p><strong>Gunanya</strong>: ukur <strong>kualitas eksekusi</strong> trader &amp; broker — KPI meja trading.</p>', 'formulas': [{'math': 'IS = (P_{exec} - P_{dec}) \\times Q + \\text{komisi} + OC_{missed}', 'symbols': ['<Tex math={String.raw`P_{dec}`} />: harga saat keputusan', '<Tex math={String.raw`P_{exec}`} />: harga eksekusi rata-rata', '<Tex math={String.raw`OC_{missed}`} />: opportunity cost order tak tereksekusi', "IS &gt; 0 untuk beli = biaya; benchmark = 'paper'"]}], 'intuisi': "Shortfall seperti <strong>selisih resep vs masakan</strong>: resep (keputusan) bilang 'butuh 1kg daging Rp100rb'; pulang dari pasar (eksekusi) bayar Rp104rb + parkir + yang kehabisan. <strong>Koki</strong> (manajer) vs <strong>belanja</strong> (trader) = skill berbeda!", 'kapan': 'TCA (transaction cost analysis): evaluasi broker/trader kuartalan.', 'worked': {'title': '📐 Contoh: IS Rp420jt (klik untuk buka)', 'body': "<p>Keputusan: beli 10jt lembar @ Rp1.000 (Rp10M). Eksekusi @ Rp1.040 + komisi Rp20jt.</p>\n<p><strong>IS</strong> = (1.040 − 1.000) × 10jt + 20jt = <strong>Rp420jt</strong>.</p>\n<p><strong>Benchmark manajer</strong>: dinilai vs Rp1.000 (paper!). Jika trader 'hemat' komisi tapi IS besar → <strong>trader buruk</strong>. KPI = <strong>IS</strong>, bukan komisi!</p>"}, 'charts': [{'data': '[{x: ["Komisi", "Delay", "Market impact", "Missed"], y: [20, 200, 200, 0], type: "bar", marker: {color: ["#94a3b8","#e8a838","#ef4444","#2a7de1"]}, text: ["Rp20jt","Rp200jt","Rp200jt","Rp0"], textposition: "outside"}]', 'title': 'Dekomposisi implementation shortfall Rp420jt', 'layout': '{xaxis: {title: "Komponen"}, yaxis: {title: "Rp juta"}, showlegend: false}', 'cara': 'Tinggi batang = biaya tiap komponen (Rp juta).', 'interpretasi': "Komisi (<strong>5%</strong>) = yang diributkan; delay + impact (<strong>95%</strong>) = yang menggerogoti. <strong>TCA yang hanya lihat komisi = buta.</strong> Trader 'murah' (komisi kecil, eksekusi lambat) bisa 10x lebih mahal dari trader 'mahal' yang cepat."}]}, {'id': 'strategi', 'toc': 'Strategi Eksekusi', 'title': 'Strategi Eksekusi — Seimbang Cepat vs Murah', 'body': '<p><strong>Definisi.</strong> <strong>Arrival price</strong>: eksekusi <em>cepat</em> (minim delay, impact besar). <strong>VWAP</strong>: ikuti volume pasar (seimbang). <strong>TWAP</strong>: bagi rata waktu (sederhana). <strong>Implementation shortfall algo</strong>: optimalkan trade-off <em>impact vs timing risk</em>.</p>\n<p><strong>Pilih</strong>: urgensi tinggi / info cepat basi → <strong>agresif</strong>; order besar / likuiditas tipis → <strong>pasif</strong> (VWAP).</p>', 'formulas': [], 'intuisi': 'Strategi eksekusi seperti <strong>menyeberang sungai</strong>: arrival = <strong>lompat langsung</strong> (cepat, basah/impact); VWAP = <strong>batu pijakan</strong> (seimbang); TWAP = <strong>jalan memutar</strong> (lambat, aman). Pilih sesuai <em>derasnya arus</em> (urgensi) &amp; <em>lebarnya sungai</em> (ukuran).', 'kapan': "Instruksi ke trader: bukan 'beli 10M' tapi 'beli 10M via VWAP 3 hari, limit...'.", 'worked': {'title': '📐 Contoh: Instruksi benar (klik untuk buka)', 'body': "<p><strong>Buruk</strong>: 'Beli Rp10M saham X.' → trader bingung → seminggu → IS Rp420jt.</p>\n<p><strong>Benar</strong>: 'Beli Rp10M via <strong>VWAP 2 hari</strong>, partisipasi maks <strong>15% volume</strong>, limit Rp1.030.'</p>\n<p><strong>Hasil</strong>: IS Rp180jt (terukur!). Manajer <strong>bertanggung jawab</strong> atas instruksi; trader atas <strong>eksekusi vs benchmark</strong>. Jelas = bisa dievaluasi.</p>"}, 'charts': []}], 'myths': [{'t': 'Biaya trading = komisi. Pilih broker termurah.', 'benar': "Komisi = <strong>5%</strong> dari total (contoh: Rp20jt dari Rp420jt!). Broker 'murah' dengan eksekusi lambat = <strong>21x lebih mahal</strong>. Ukur <strong>implementation shortfall</strong> — itulah harga sebenarnya. <strong>TCA &gt; tarif komisi.</strong>"}, {'t': 'Eksekusi pelan = hati-hati = murah.', 'benar': "<strong>Seminggu 'hati-hati' = Rp420jt; 1 hari agresif mungkin Rp150jt.</strong> Lambat = delay cost + timing risk. 'Hati-hati' tanpa ukuran = <em>mahal yang tersembunyi</em>. Optimal = <strong>seimbang</strong> (VWAP), bukan selambat mungkin."}], 'tips': ["<strong>Selalu beri benchmark eksekusi.</strong> 'Beli via VWAP' tanpa benchmark = tidak bisa dinilai. Arrival price / VWAP = penggaris trader. Tanpa penggaris, semua klaim 'eksekusi baik' = omong kosong.", '<strong>Pisahkan alpha manajer dari skill trader.</strong> Manajer dinilai vs harga keputusan (paper); trader dinilai vs IS. Campur = tidak ada yang bertanggung jawab.'], 'labs': [{'heading': 'Kalkulator Implementation Shortfall', 'intro': 'Hitung IS dan dekomposisinya dari data eksekusi.', 'title': 'Lab 1 — Kalkulator Shortfall', 'hint': 'Ubah P_EXEC 1040 → 1010 (eksekusi cepat). IS anjlok — kecepatan menghemat!', 'code': '# Implementation shortfall\nP_DEC = 1000      # harga saat keputusan\nP_EXEC = 1040     # harga eksekusi rata2 (ubah!)\nQ = 10_000_000    # lembar\nKOMISI = 20_000_000\n\nbiaya_harga = (P_EXEC - P_DEC) * Q\nIS = biaya_harga + KOMISI\n\nprint(f"Biaya harga (delay+impact): Rp{biaya_harga/1e9:.2f} M")\nprint(f"Komisi                    : Rp{KOMISI/1e9:.2f} M")\nprint(f"IS total                  : Rp{IS/1e9:.2f} M ({IS/(P_DEC*Q):.1%})")\nprint(f"Porsi komisi              : {KOMISI/IS:.0%}")\nprint()\nprint("Porsi komisi kecil = TCA harus ukur implisit!")\n'}, {'heading': 'Simulator VWAP', 'intro': 'Simulasikan eksekusi VWAP vs agresif: trade-off impact vs delay.', 'title': 'Lab 2 — Simulator VWAP', 'hint': 'Ubah HARI 3 → 1 (agresif). Impact naik, delay turun — cari titik optimal!', 'code': '# VWAP vs agresif: impact vs delay\nimport random\nrandom.seed(7)\nQ_TOTAL = 10_000_000\nP0 = 1000\nHARI = 3          # lama eksekusi (ubah!)\nVOL_HARIAN = 50_000_000\n\ndef eksekusi(hari):\n    sisa, biaya, harga = Q_TOTAL, 0, P0\n    for h in range(hari):\n        q = sisa/(hari-h)\n        partisipasi = q/VOL_HARIAN\n        impact = 20 * partisipasi       # Rp per lembar\n        drift = random.uniform(-5, 15)  # pergerakan pasar\n        harga += drift\n        biaya += q*(impact) + q*drift\n        sisa -= q\n    return biaya\n\nb = eksekusi(HARI)\nprint(f"Eksekusi {HARI} hari: biaya implisit Rp{b/1e6:.0f}jt ({b/(P0*Q_TOTAL):.2%})")\nprint()\nprint("Lambat: delay/drift besar. Cepat: impact besar.")\nprint("VWAP = titik seimbang. Ukur, jangan kira-kira!")\n'}], 'decisions': [{'kondisi': 'Info cepat basi / urgensi tinggi', 'pakai': 'Arrival price (agresif)', 'alasan': 'Delay &gt; impact.', 'contoh': 'Earnings surprise.'}, {'kondisi': 'Order besar, likuiditas tipis', 'pakai': 'VWAP multi-hari + limit', 'alasan': 'Impact terkendali.', 'contoh': 'Rp10M small-cap.'}, {'kondisi': 'Evaluasi broker/trader', 'pakai': 'TCA: IS vs benchmark', 'alasan': 'Ukur total.', 'contoh': 'Review kuartalan.'}, {'kondisi': 'Instruksi ke trader', 'pakai': 'Spesifik: algo + horizon + limit', 'alasan': 'Bisa dievaluasi.', 'contoh': "'VWAP 2 hari, maks 15% vol'."}], 'rule10': '<ol><li><strong>Ukur IS</strong>, bukan komisi.</li><li><strong>Pisahkan</strong> manajer vs trader.</li><li><strong>Instruksi spesifik</strong> + benchmark.</li><li><strong>Seimbang</strong>: cepat vs murah.</li></ol>', 'case': {'toc': 'Mini-Case: Rp420 Jt', 'title': 'Seminggu yang Mahal', 'body': '<p>Beli Rp10M @ Rp1.000, eksekusi seminggu @ Rp1.040. Komisi Rp20jt. IS = Rp420jt.</p>', 'q': '(a) Dekomposisi IS? (b) Apa kesalahan keputusan? (c) Instruksi yang benar?', 'pembahasan': "<p>(a) <strong>Delay Rp200jt + impact Rp200jt + komisi Rp20jt</strong> = Rp420jt (4,2%).</p>\n<p>(b) <strong>Instruksi vague</strong> ('beli Rp10M') + <strong>asumsi 'pelan = murah'</strong> + <strong>KPI komisi</strong> (bukan IS).</p>\n<p>(c) <strong>'VWAP 2 hari, partisipasi ≤15%, limit Rp1.030'</strong> + evaluasi trader vs IS. Manajer vs harga keputusan.</p>"}, 'quiz': [{'q': 'IS = Rp420jt, komisi Rp20jt. Porsi komisi?', 'options': ['100%', '≈ 5% — gunung es', '50%', '21%'], 'correct': 1, 'why': 'Benar: 20/420 ≈ 5%. 95% = delay + impact (tak terlihat). TCA wajib ukur implisit.'}, {'q': "Eksekusi seminggu 'hati-hati' vs 1 hari agresif. Mana bisa lebih murah?", 'options': ['Seminggu selalu', '1 hari bisa (delay lebih kecil dari impact)', 'Sama', 'Tidak terkait'], 'correct': 1, 'why': 'Benar: lambat = delay cost besar. Optimal = seimbang, bukan selambat mungkin.'}, {'q': 'KPI trader yang benar?', 'options': ['Komisi terendah', 'Implementation shortfall vs benchmark', 'Kecepatan', 'Volume'], 'correct': 1, 'why': 'Benar: IS mengukur kualitas total. Komisi rendah + IS besar = trader buruk.'}, {'q': 'Order besar di saham tidak likuid. Strategi?', 'options': ['Arrival price agresif', 'VWAP multi-hari + limit partisipasi', 'Market order langsung', 'Tunda'], 'correct': 1, 'why': 'Benar: pasif & terkendali untuk likuiditas tipis; agresif = impact meledak.'}, {'q': 'Manajer dinilai vs apa?', 'options': ['Harga eksekusi', 'Harga keputusan (paper portfolio)', 'Komisi', 'IHSG'], 'correct': 1, 'why': 'Benar: pisahkan skill manajer (vs paper) dari skill trader (IS). Campur = kabur tanggung jawab.'}], 'rangkum': ['<strong>Biaya</strong>: eksplisit (komisi) vs implisit (spread, impact, delay, missed) — gunung es.', '<strong>IS</strong> = paper − real; KPI meja trading.', '<strong>Strategi</strong>: arrival (cepat), VWAP (seimbang), TWAP (rata), IS-algo (optimal).', '<strong>Instruksi</strong>: spesifik (algo + horizon + limit) + benchmark.', '<strong>Aturan</strong>: ukur total; pisahkan manajer vs trader; seimbang cepat vs murah.', "<strong>Pelajaran</strong>: 'hati-hati' tanpa ukuran = mahal tersembunyi."], 'prev': ['pm-c9-derivatives-overlay', 'PM-C9'], 'next': ['pm-c11-ethics-esg', 'PM-C11']}, {'slug': 'pm-c11-ethics-esg', 'id': 'PM-C11', 'track': 'Portfolio Management', 'title_html': 'Ethics Lanjutan & ESG:<br/>Uang yang Bersih', 'title_plain': 'Ethics Lanjutan & ESG Integration', 'chapter_summary': 'CFA L3 etika praktik: soft dollars, directed brokerage, fair dealing IPO, lalu integrasi ESG — faktor material, engagement vs exclusion, dan jebakan rating divergence & greenwashing. Lab pemeriksa soft-dollar & agregator skor ESG.', 'tujuan': ['Menjelaskan isu etika praktik: soft dollars, directed brokerage, IPO.', 'Menjelaskan integrasi ESG vs exclusion vs engagement.', 'Mengidentifikasi greenwashing dan rating divergence.', 'Merancang kebijakan ESG yang kredibel.'], 'story_title': "Cerita: Dana 'Hijau' yang Berisi Batubara", 'story': "<p><strong>2023</strong>: reksadana <strong>'Green Future'</strong> meraup <strong>Rp2 triliun</strong> — marketing: <em>'100% ESG!'</em> <strong>Jurnalis</strong> bedah portofolio: <strong>15% batubara &amp; sawit bermasalah</strong>! Manajer berkilah: <em>'rating ESG kami... dari provider X'</em> (yang memberi skor tinggi ke semua kliennya!).</p>\n<p>Twist-nya: <strong>regulator</strong> denda + investor <strong>redeem massal</strong>. 'Hijau' di brosur = <strong>greenwashing</strong> — dan pasar kini menghukumnya <em>lebih keras</em> dari sekadar 'tidak hijau'. <strong>Klaim ESG palsu &gt; tidak klaim sama sekali.</strong> Lesson ini: integritas sebagai strategi.</p>", 'concepts': [{'id': 'etikapraktik', 'toc': 'Etika Praktik', 'title': 'Etika Praktik — Ujian Sehari-hari', 'body': "<p><strong>Definisi.</strong> <strong>Soft dollars</strong>: komisi trading dipakai bayar <em>riset</em> — boleh jika <em>manfaat klien</em> &amp; <em>disclose</em>; haram jika untuk <em>sewa kantor</em>! <strong>Directed brokerage</strong>: klien arahkan broker tertentu — <em>waspadai</em> eksekusi buruk. <strong>Fair dealing IPO</strong>: alokasi <em>proporsional</em>, tidak untuk 'klien favorit'.</p>\n<p><strong>Prinsip</strong>: <strong>loyalty + disclosure</strong> — jika ragu, <em>ungkapkan &amp; minta persetujuan</em>.</p>", 'formulas': [], 'intuisi': 'Soft dollars seperti <strong>uang belanja titipan</strong>: dititipi Rp100rb beli sayur (trading); kembalian dipakai beli <em>bumbu</em> (riset, untuk masakan klien ✓) vs <em>pulsa pribadi</em> (✗!). Bedanya = <strong>untuk siapa manfaatnya</strong> + <strong>bilang ke yang nitip</strong>.', 'kapan': 'Setiap penggunaan komisi klien; alokasi produk terbatas.', 'worked': {'title': '📐 Contoh: Riset vs sewa (klik untuk buka)', 'body': "<p>Manajer pakai soft dollars Rp500jt/thn: <strong>Rp300jt riset</strong> (data, analis) + <strong>Rp200jt 'terminal &amp; sewa'</strong>.</p>\n<p><strong>Audit</strong>: riset ✓ (manfaat klien, disclose). Sewa ✗ — <strong>pelanggaran</strong> (manfaat manajer!).</p>\n<p><strong>Solusi</strong>: bayar sewa dari <strong>fee manajemen</strong> (uang sendiri!), disclose riset ke klien. <strong>Aturan praktis</strong>: 'berani tulis di factsheet?' — jika tidak, jangan lakukan.</p>"}, 'charts': []}, {'id': 'esg', 'toc': 'Integrasi ESG', 'title': 'Integrasi ESG — Faktor, Bukan Filter', 'body': '<p><strong>Definisi.</strong> <strong>Integrasi</strong>: faktor ESG <em>material</em> masuk <strong>analisis valuasi</strong> (risiko iklim → arus kas!). <strong>Exclusion</strong>: coret sektor (senjata tumpul). <strong>Engagement</strong>: <em>aktif</em> perbaiki perusahaan (voting, dialog) — bukti dampak <strong>terkuat</strong>.</p>\n<p><strong>Materialitas</strong>: ESG yang <em>relevan finansial</em> per sektor (SASB): emisi untuk tambang, privasi data untuk tech.</p>', 'formulas': [], 'intuisi': "Integrasi ESG seperti <strong>cek kesehatan</strong>: bukan 'tolak pasien perokok' (exclusion), tapi <strong>masukkan riwayat merokok ke diagnosis</strong> (integrasi) + <strong>ajak berhenti</strong> (engagement). Dokter yang mengabaikan riwayat = malpraktik; yang menolak pasien = bukan dokter.", 'kapan': 'Analisis fundamental: matriks materialitas per sektor wajib.', 'worked': {'title': '📐 Contoh: Tambang vs ESG (klik untuk buka)', 'body': '<p>Tambang batubara: <strong>risiko transisi</strong> (pajak karbon!) → arus kas −20% skenario 2030 → <strong>valuasi −25%</strong> (integrasi!).</p>\n<p><strong>Exclusion</strong>: coret → lewatkan <em>turnaround</em> (diversifikasi ke nikel!). <strong>Engagement</strong>: voting paksa <em>capex hijau</em> + target emisi.</p>\n<p><strong>Hasil</strong>: valuasi jujur + perusahaan membaik = <strong>return + dampak</strong>. Itulah ESG yang <em>bekerja</em>.</p>'}, 'charts': [{'data': '[{x: ["Provider A","Provider B","Provider C","Provider D"], y: [85,62,78,45], type: "bar", marker: {color: ["#2a7de1","#e8a838","#16a34a","#ef4444"]}, text: ["85","62","78","45"], textposition: "outside"}]', 'title': 'Skor ESG satu perusahaan dari 4 provider (ilustrasi)', 'layout': '{xaxis: {title: "Provider"}, yaxis: {title: "Skor ESG (0-100)"}, showlegend: false}', 'cara': 'Tinggi batang = skor ESG perusahaan <em>sama</em> dari provider berbeda.', 'interpretasi': "<strong>45–85 untuk perusahaan yang sama!</strong> Rating ESG <strong>divergen</strong> (korelasi antar-provider ~0,5 vs rating kredit ~0,99). <strong>Jangan beli skor mentah</strong> — pahami <em>metodologi</em>, pakai untuk <em>riset</em> bukan <em>label</em>. 'Green Future' memakai provider termurah hati = greenwashing by proxy."}]}, {'id': 'greenwash', 'toc': 'Greenwashing', 'title': 'Greenwashing — Dosa & Deteksi', 'body': "<p><strong>Definisi.</strong> <strong>Greenwashing</strong>: klaim ESG <em>melebihi</em> realita. <strong>Deteksi</strong>: (1) <em>vague</em> ('komitmen hijau' tanpa angka); (2) <em>cherry-pick</em> (1 proyek hijau, 99% kotor); (3) <em>provider shopping</em> (pilih rating tertinggi); (4) <em>tidak ada voting record</em> (ngaku engagement, tidak pernah voting!).</p>\n<p><strong>Pertahanan</strong>: <em>kebijakan tertulis</em> + <em>metrik terukur</em> + <em>audit independen</em> + <em>transparansi penuh</em>.</p>", 'formulas': [], 'intuisi': 'Greenwashing seperti <strong>kosmetik tebal</strong>: dari jauh glowing (brosur), dekat retak (portofolio). Regulator &amp; jurnalis = <strong>cahaya terang</strong> — makin terang, makin terlihat retaknya. Solusi: <strong>skincare</strong> (perbaiki beneran), bukan <strong>makeup</strong> (klaim).', 'kapan': "Due diligence produk 'ESG'; desain kebijakan sendiri.", 'worked': {'title': "📐 Contoh: Audit 'Green Future' (klik untuk buka)", 'body': "<p><strong>Red flags</strong>: (1) '100% ESG' tanpa definisi; (2) 15% batubara; (3) provider X (skor murah hati); (4) <strong>voting record: nol</strong> (tidak pernah engagement!).</p>\n<p><strong>Kebijakan kredibel</strong>: definisi tertulis + <em>ambang batas</em> (batubara &lt; 5% &amp; turun tiap tahun) + <em>2 provider</em> + <em>voting dipublikasi</em> + <em>audit tahunan</em>.</p>\n<p><strong>Hasil</strong>: AUM turun 40% (jangka pendek) → <strong>kepercayaan pulih</strong> (jangka panjang). Integritas = <strong>strategi bisnis</strong>.</p>"}, 'charts': []}], 'myths': [{'t': 'ESG = return lebih rendah (biaya moral).', 'benar': 'Meta-studi: integrasi ESG <strong>netral hingga positif</strong> untuk return — karena ESG material = <strong>risiko yang diukur</strong> (bukan amal!). Yang menurunkan return = <em>exclusion membabi buta</em> (semesta menyempit). <strong>Integrasi ≠ donasi.</strong>'}, {'t': 'Skor ESG tinggi = perusahaan baik. Beli yang skor 90+.', 'benar': "Skor <strong>45–85 untuk perusahaan sama</strong> (divergence!) + bisa <strong>dibeli</strong> (provider shopping). Skor = <em>opini bermetodologi</em>, bukan fakta. Pakai sebagai <strong>starting point riset</strong>, bukan keputusan. 'Green Future' = korban skor mentah."}], 'tips': ['<strong>Tulis kebijakan ESG 1 halaman.</strong> Definisi + ambang batas + provider + voting policy + audit. Tanpa tulisan = klaim = calon greenwashing. Satu halaman melindungi dari denda & redeem.', "<strong>Uji 'berani diumumkan?'</strong> Untuk tiap keputusan etika abu-abu (soft dollars, alokasi IPO): 'berani tulis di factsheet?' Jika tidak — jangan lakukan. <strong>Transparansi = kompas.</strong>"], 'labs': [{'heading': 'Pemeriksa Soft-Dollar', 'intro': 'Audit penggunaan komisi: mana yang boleh, mana pelanggaran.', 'title': 'Lab 1 — Pemeriksa Soft-Dollar', 'hint': 'Ubah SEWA 200 → 0 dan FEE_BAYAR True. Status berubah BERSIH — struktur yang benar!', 'code': '# Pemeriksa soft-dollar: manfaat klien vs manajer?\nRISET = 300   # Rp jt (data, analis)\nSEWA = 200    # Rp jt (\'terminal & sewa\') - ubah!\nDISCLOSE = True\nFEE_BAYAR = False  # sewa dibayar dari fee manajemen? (ubah!)\n\nprint(f"Riset Rp{RISET}jt: {\'OK\' if True else \'\'} (manfaat klien)" + (" + disclose" if DISCLOSE else " TANPA DISCLOSE!"))\nmasalah = []\nif SEWA > 0 and not FEE_BAYAR:\n    masalah.append(f"Sewa Rp{SEWA}jt dari soft-dollar = PELANGGARAN (manfaat manajer!)")\nif not DISCLOSE:\n    masalah.append("Tanpa disclosure = pelanggaran")\nif masalah:\n    print("HASIL: BERMASALAH")\n    for m in masalah: print(" -", m)\nelse:\n    print("HASIL: BERSIH (riset disclose + operasional dari fee sendiri)")\nprint("\\nAturan: \'berani tulis di factsheet?\'")\n'}, {'heading': 'Agregator Skor ESG', 'intro': 'Lihat rating divergence: satu perusahaan, banyak skor.', 'title': 'Lab 2 — Agregator ESG', 'hint': 'Ubah skor PROVIDER_D 45 → 80 (provider murah hati). Rata-rata naik — manipulasi semudah itu!', 'code': '# Rating divergence: jangan telan skor mentah\nskor = {"Provider A": 85, "Provider B": 62, "Provider C": 78, "Provider D": 45}  # ubah D!\nvals = list(skor.values())\nimport statistics\nprint("Skor perusahaan X:")\nfor k, v in skor.items(): print(f"  {k}: {v}")\nprint(f"\\nRentang: {min(vals)}-{max(vals)} (selisih {max(vals)-min(vals)}!)")\nprint(f"Rata2: {statistics.mean(vals):.0f}, Std: {statistics.pstdev(vals):.0f}")\nprint()\nprint("Korelasi antar-provider ~0,5 (kredit: ~0,99).")\nprint("Pakai skor untuk RISET (kenapa beda?), bukan LABEL.")\nprint("Provider shopping = greenwashing by proxy.")\n'}], 'decisions': [{'kondisi': 'Pakai komisi klien', 'pakai': 'Hanya untuk manfaat klien + disclose', 'alasan': 'Loyalty.', 'contoh': 'Riset OK; sewa TIDAK.'}, {'kondisi': 'Alokasi IPO terbatas', 'pakai': 'Proporsional, terdokumentasi', 'alasan': 'Fair dealing.', 'contoh': 'Tidak untuk favorit.'}, {'kondisi': 'Analisis fundamental', 'pakai': 'Integrasi ESG material per sektor', 'alasan': 'Risiko = valuasi.', 'contoh': 'Pajak karbon → arus kas.'}, {'kondisi': "Klaim 'ESG' produk", 'pakai': 'Kebijakan tertulis + metrik + audit', 'alasan': 'Anti-greenwashing.', 'contoh': '1 halaman + voting record.'}], 'rule10': '<ol><li><strong>Loyalty + disclosure</strong> selalu.</li><li><strong>Integrasi</strong>, bukan sekadar exclusion.</li><li><strong>Engagement</strong> &gt; label.</li><li><strong>Skor</strong> = riset, bukan keputusan.</li></ol>', 'case': {'toc': 'Mini-Case: Green Future', 'title': "Dana 'Hijau' Berisi Batubara", 'body': "<p>'Green Future' Rp2T: klaim '100% ESG', isi 15% batubara, provider X murah hati, voting record nol. Denda + redeem massal.</p>", 'q': '(a) Identifikasi 4 red flags. (b) Rancang kebijakan kredibel. (c) Pelajaran etika umum?', 'pembahasan': "<p>(a) <strong>Vague</strong> (tanpa definisi) + <strong>holdings vs klaim</strong> + <strong>provider shopping</strong> + <strong>voting nol</strong> (engagement palsu).</p>\n<p>(b) <strong>Definisi tertulis</strong> + ambang (batubara &lt;5% menurun) + <strong>2 provider</strong> + <strong>voting dipublikasi</strong> + <strong>audit independen tahunan</strong>.</p>\n<p>(c) <strong>Klaim palsu &gt; tidak klaim.</strong> Integritas = strategi bisnis jangka panjang. Uji 'berani diumumkan?' untuk semua area abu-abu.</p>"}, 'quiz': [{'q': 'Soft dollars Rp500jt: Rp300jt riset + Rp200jt sewa. Penilaian?', 'options': ['Semua OK', 'Riset OK (disclose); sewa = pelanggaran', 'Semua pelanggaran', 'Terserah'], 'correct': 1, 'why': 'Benar: uji = untuk siapa manfaatnya? Riset → klien ✓. Sewa → manajer ✗ (bayar dari fee sendiri!).'}, {'q': 'Skor ESG 45–85 untuk perusahaan sama. Implikasi?', 'options': ['Pilih tertinggi', 'Divergence: pahami metodologi, pakai untuk riset', 'Rata-ratakan', 'Abaikan ESG'], 'correct': 1, 'why': "Benar: korelasi antar-provider ~0,5. Skor mentah = opini. 'Green Future' hancur karena provider shopping."}, {'q': 'Bukti dampak ESG terkuat?', 'options': ['Exclusion', 'Engagement (voting, dialog)', 'Marketing hijau', 'Skor tinggi'], 'correct': 1, 'why': 'Benar: engagement aktif memperbaiki perusahaan. Exclusion = cuci tangan; voting record nol = engagement palsu.'}, {'q': "Alokasi IPO terbatas ke 'klien favorit'. Ini?", 'options': ['OK', 'Pelanggaran fair dealing', 'Strategi', 'Rahasia dapur'], 'correct': 1, 'why': 'Benar: alokasi harus proporsional & terdokumentasi. Favoritisme = melanggar loyalty ke klien lain.'}, {'q': 'Pertahanan greenwashing terbaik?', 'options': ['Brosur lebih bagus', 'Kebijakan tertulis + metrik + audit + transparansi', 'Ganti provider', 'Diam'], 'correct': 1, 'why': 'Benar: klaim tanpa bukti = calon denda. Satu halaman kebijakan + voting record + audit = kredibel.'}], 'rangkum': ['<strong>Soft dollars</strong>: hanya manfaat klien + disclose; operasional dari fee.', '<strong>Fair dealing</strong>: IPO proporsional; directed brokerage waspadai eksekusi.', '<strong>ESG</strong>: integrasi (material) &gt; exclusion; engagement (voting) = dampak.', '<strong>Divergence</strong>: skor 45–85; pahami metodologi; anti provider-shopping.', '<strong>Greenwashing</strong>: klaim &gt; realita; deteksi via vagueness, holdings, voting.', "<strong>Aturan</strong>: 'berani diumumkan?'; integritas = strategi."], 'prev': ['pm-c10-trading-execution', 'PM-C10'], 'next': ['pm-d1-data-harga', 'PM-D1']}]
